    ['Promathia Mission 8-1'] = {
        title        = 'Garden of Antiquity',
        starting_npc = 'Al\'Taieu - Crystalline Field - (H-11)',
        subtitle     = 'Seeker of the Light',
        repeatable   = 'No',
        description  = 'The celestial capital of Al\'Taieu truly exists. Though vastly altered during the ten thousand-year span of their seclusion, the ancients remain alive in the city. Nag\'molada heads for the palace, while you and your companions follow in his wake...',
        series       = 'Chains of Promathia',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Examine the Crystalline Field at (H-11) in Al\'Taieu for a brief cutscene.', sub = {
                { 'The Auroral Updraft at (H-12) (red pillar of light) returns you to Sealion\'s Den; Sueleen sends you back to Al\'Taieu.' },
            } },
            { 'Examine the 3 Rubious Crystals to spawn trios of Ru\'aern NMs; defeat each trio and examine the crystal again for a cutscene (3 total).', sub = {
                { 'The Auroral Updrafts at (E-8) and (L-8) shuttle you back to (H-12) to shorten travel.' },
                { 'Auroral Updraft teleports count as a zone — non-persistent buffs wear and all trusts are dismissed.' },
                { 'If others are spawning the NMs, the interaction point will show \'There is nothing of interest here.\' for up to ~2 minutes.' },
