    ['Promathia Mission 8-2'] = {
        title        = 'A Fate Decided',
        starting_npc = 'Grand Palace of Hu\'Xzoi - Particle Gate - (H-8)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Nag\'molada has descended into the depths of the palace in search of the Chamber of Eventide. Join Prishe in her pursuit of the Kuluu diplomat.',
        series       = 'Chains of Promathia',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Examine the eastern Particle Gate at (H-8) in the Grand Palace of Hu\'Xzoi for a cutscene that starts the mission; examine it again to enter.', sub = {
                { 'The northern Particle Gate next to the Home Point goes to the Garden of Ru\'Hmet — wrong door.' },
            } },
            { 'Navigate Hu\'Xzoi by escorting Quasilumin orb NPCs (upper and lower level — see map\'s blue line).' },
            { 'When a Particle Gate is closed, check a nearby Cermet Alcove to spawn a Quasilumin that walks a fixed route; you can stop and start it like an escort NPC.' },
            { 'Protect the Quasilumin to its destination — it opens Particle Gates along the way, ends at another Cermet Alcove; check it there to open the final gate.' },
            { 'Watch for shapeshifting Ix\'ghrah and Eo\'ghrah, and the Eo\'zdei at the end of the first and second escort.', sub = {
                { 'Stationary Quasilumins reward map progress — talking to all ten unlocks a Grand Palace map when you talk to one again.' },
            } },
            { '── Complete Route ──' },
            { 'Map 1 (Upper, M1) (J-8) escort — 5 minute limit.' },
            { 'Map 1 (L-7) transporter.' },
            { 'Map 2 (Basement, M2) (L-8) escort — 30 minute limit.' },
            { 'Map 2 (I-10) escort — 30 minute limit.' },
            { 'Map 2 (G-12) transporter.' },
            { 'Map 1 (G-10) escort — 40 minute limit.', sub = {
                { 'Players who already completed When Angels Fall can join here via the west door from the lobby.' },
            } },
            { 'Map 1 (G-4) transporter.' },
            { 'Continue to Map 2 (H-8) for the NM fight.' },
            { 'Enter the room and examine the Cermet Portal to spawn an Ix\'ghrah; it shifts between 4 forms — ball, bird, spider, human.', sub = {
                { 'Easily soloable around level 75 with Trusts; trivial at Item Level.' },
                { 'Spider form — damaged by both physical and magic, but most dangerous to the tank (Mighty Strikes, Sickle Slash ignores Utsusemi).' },
                { 'Bird form — hard to hit with weapons, takes heavy magic damage (Perfect Dodge, Damnation Dive).' },
                { 'Orb form — more damage from weapons, less from magic; casts elemental -ga III spells, uses Manafont and Hexidiscs.' },
                { 'Humanoid form — barely takes or deals damage; uses Invincible and Vorpal Blade.' },
            } },
            { 'Examine the Cermet Portal again after defeating it for a cutscene.' },
            { 'Return to the palace entrance and examine the Gate of the Gods to enter The Garden of Ru\'Hmet.', sub = {
                { 'Faster: Warp/Warp Ring out and teleport to Home Point #1 in Grand Palace of Hu\'Xzoi (via Lumoria).' },
            } },
        },
    },
    ['Promathia Mission 8-3'] = {
        title        = 'When Angels Fall',
        starting_npc = 'N/A',
        subtitle     = 'Warrior of the Crystal',
        repeatable   = 'No',
        description  = 'The Gate of the Gods--the portal leading to the highest level of the palace--has opened. While your companions scramble to reach the audience chamber, you must find which of the five towers will return you into the light...',
        series       = 'Chains of Promathia',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Check the Gate of the Gods (next to the Home Point) for a cutscene; this is required to access the upper floors (3-4).' },
            { '── Retrieving Your Light ──' },
            { 'Climb to the 4th floor of your race\'s Tower — there are 5 Towers at the points of the map:', sub = {
                { 'Key Item Light of Mea — Elvaan (East).' },
                { 'Key Item Light of Dem — Mithra (West).' },
                { 'Key Item Light of Holla — Tarutaru (Southwest).' },
                { 'Key Item Light of Vahzl — Hume (North).' },
                { 'Key Item Light of Al\'Taieu — Galka (Southeast).' },
            } },
            { 'On the 4th floor, check the Ebon Panel twice — once for a cutscene and a new title, once for the Key Item of your race.', sub = {
                { 'Any tower\'s Ebon Panel progresses the mission, but only the matching tower gives the second cutscene and title.' },
                { 'Can be done solo or with party; each person must climb their own race\'s Tower for the title.' },
                { 'After checking, warp out and Home Point back for the next section to save time.' },
            } },
            { '── Brands of Dawn and Twilight ──' },
            { 'Go to the central area of The Garden of Ru\'Hmet on the first floor.', sub = {
                { 'The elevator cannot be reached directly — run East, then North, then West to access from the other side.' },
            } },
            { 'Slip past the four spinning Qn\'zdei on each side of the elevator.', sub = {
                { 'Doors stay open while Qn\'zdei are on their pedestals; aggro makes them move and the far door closes.' },
                { 'Immune to Sleep, Lullaby, and Repose; respawn takes 5 minutes if killed.' },
                { 'They detect only by True Sight on the large blue \'eye\' side — hug the wall and you only avoid 2 of them.' },
                { 'If the door closes, kill them and auto-run toward the door; you\'ll enter on respawn.' },
            } },
            { 'Step onto the platform in the elevator room and choose to ascend.', sub = {
                { 'Register the Home Point in front of the elevator ramp.' },
            } },
            { 'Navigate this floor (Map 2) to collect both Key Item Brand of Twilight (south) and Key Item Brand of Dawn (north).', sub = {
                { 'Warp Distortions de-summon Trusts.' },
                { 'Brand of Dawn is faster; Brand of Twilight has a longer path.' },
                { 'To save time, warp out and Home Point back to the elevator after obtaining each key item.' },
            } },
            { '── Burning Circle Fight ──' },
            { 'Return to the central elevator and ascend until reaching the 3rd floor of The Garden of Ru\'Hmet.', sub = {
                { 'Both key items are required to ascend twice; the 2nd ascent has a different animation.' },
            } },
            { 'Check the Particle Gate on the 3rd floor for a cutscene, then check it again to enter the BC.' },
            { 'You begin at the north end of the room facing south at the pots.', sub = {
                { 'Soloable level 80+ with Trust, very hard at 75+, trivial at Item Level.' },
            } },
            { 'Defeat the four Ix\'zdei NMs.', sub = {
                { 'Two larger are RDM-type; two smaller are BLM-type.' },
                { 'All immune to silence and heavily resistant to sleep; Elemental Seal needed to sleep them.' },
                { 'Low-HP pots may flee to spawn and regen to full in seconds — Stun and Weapon Skills can interrupt this.' },
                { 'Safest place to die is the south door near the BLM pots; wait for pots to reset before Reraising.' },
                { 'Every surviving member receives 1,000 EXP on win.' },
            } },
            { 'Walk across the empty room and check the Luminous Convergence for a cutscene.' },
            { 'Head south to the Particle Gate, choose \'Leave the Garden of Ru\'Hmet\', then \'Yes\' to return to the Grand Palace.', sub = {
                { 'Head south to zone into Al\'Taieu for a cutscene to finish this mission and begin the next.' },
            } },
        },
    },
    ['Promathia Mission 8-4'] = {
        title        = 'Dawn',
        starting_npc = 'N/A',
        subtitle     = 'Banisher of Emptiness',
        repeatable   = 'Yes',
        description  = 'Revelations of truth accompany the awakening of Promathia. The world and its people stand in the twilight of the apocalypse. Dawn Goddess Altana, grant us victory!',
        series       = 'Chains of Promathia',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Zone into The Garden of Ru\'Hmet and pass through the Cermet Portal to reach the main Garden elevator.', sub = {
                { 'Use Home Point #1 of The Garden of Ru\'Hmet.' },
            } },
            { 'Choose to descend to zone into Empyreal Paradox.' },
            { 'Examine the Transcendental Radiance for a cutscene, then examine it again to enter the \'Dawn\' battleground.' },
        },
    },
    ['Promathia Mission 8-5'] = {
        title        = 'The Last Verse',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'N/A',
        series       = 'Chains of Promathia',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'This mission has no description. It is the final mission of both Rise of the Zilart (Zilart Mission 18) and Chains of Promathia (Promathia Mission 8-5), appearing in your log on completion of Apocalypse Nigh to signify the storylines are finished.' },
        },
    },
}

