quest_info['wotgmissions'] = {
    ['A Hawk in Repose'] = {
        title        = 'A Hawk in Repose',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Word has it that an unknown individual is often seen paying tribute to Sir Ragelise\'s grave out in Batallia Downs. Could it be that this man possesses the information you seek?',
        series       = 'Wings of the Goddess',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Obtain a Lilac (120 gil at M & P\'s Market in Upper Jeuno HP #1 (E), from Areebah at (H-6); buy two since one is needed for a later quest).' },
            { 'Examine the Weathered Gravestone in Batallia Downs at (I-10), up the hill, for a cutscene.', sub = {
                { 'Fastest route: use The Eldieme Necropolis Survival Guide and walk outside to Batallia Downs.' },
                { 'If you see "You see the weathered gravestone." you did not complete Another World, or another quest/mission took priority.' },
            } },
            { 'Trade a Lilac to the Weathered Gravestone.' },
        },
    },
    ['A Nation on the Brink'] = {
        title        = 'A Nation on the Brink',
        starting_npc = 'Batallia Downs (S)',
        subtitle     = 'Battle of Jeuno Veteran',
        repeatable   = 'No',
        description  = 'Despite Lilisette\'s repeated protests and the imminent arrival of reinforcements from the three nations, the surrender ceremony is set to take place in the depths of Jeuno\'s underground. Will this be the end of the four-nation',
        series       = 'Wings of the Goddess',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Examine the Underpass Hatch in Batallia Downs (S) at (J-9)/(K-9), on the rampart inside a tower, for a cutscene.', sub = {
                { 'If you have progressed in Voidwatch, use the Atmacite Refiner in Sauromugue Champaign (S); otherwise the Campaign Arbiter from your allied nation gets you close.' },
            } },
            { '── A Nation on the Brink (Battlefield) ──' },
            { 'Examine the Underpass Hatch again to enter Everbloom Hollow for the battlefield.' },
            { 'Up to six players may enter, provided each has Key Item: Underpass hatch key or has cleared the fight; the party leader must have the key item.' },
            { 'Defeat One-eyed Gwajboj, who spawns after the beastmen waves are cleared (Paladin; may use Invincible multiple times).' },
            { 'Trusts can be summoned.' },
            { 'All mobs inside are immune to all forms of Sleep; Bind and Gravity immunity unknown (typically the case for WotG NMs).' },
            { 'You are assisted by 9 NPCs: Rongelouts N Distaud, Zazarg, Romaa Mihgo, 2x Iron Ram Knights, 2x 7th Cohors Legionnaires, 2x Cobra Mercenaries.', sub = {
                { 'Northwest: Zazarg + 7th Cohors Legionnaires fight Ruby Quadav + 4 Nickel Quadavs, then 2 Ruby Quadavs + 3 Nickel Quadavs.' },
                { 'Northeast: Rongelouts N Distaud + Iron Ram Knights fight Orcish Hexspinner + 4 Orcish Gladiators, then 2 Orcish Hexspinners + 3 Orcish Gladiators.' },
                { 'South: Romaa Mihgo + Cobra Mercenaries fight Yagudo Abbot + 4 Yagudo Missionaries, then 2 Yagudo Abbots + 3 Yagudo Missionaries.' },
            } },
            { '── Wrap Up ──' },
            { 'Defeating One-eyed Gwajboj triggers a cutscene; you receive the Jeunoan Flag, completing the mission.', sub = {
                { 'If your inventory is full, retrieve it from the ??? just north of the fight\'s entrance on top of some barrels.' },
            } },
            { 'Continue the national storylines:', sub = {
                { 'Quelling the Storm — if previously aligned with Bastok.' },
                { 'The Price of Valor — if previously aligned with San d\'Oria.' },
                { 'The Long March North — if previously aligned with Windurst.' },
            } },
        },
    },
    ['A Sanguinary Prelude'] = {
        title        = 'A Sanguinary Prelude',
        starting_npc = 'Beaucedine Glacier (S)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'You have been granted permission to accompany the Madder Falcons and the Red Roses to the Northlands Take advantage of this opportunity to unearth clues that may lead to the recovery of Lilisette and Portia.',
        series       = 'Wings of the Goddess',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Zone into Beaucedine Glacier (S) for a cutscene.' },
        },
    },
    ['A Spoonful of Sugar'] = {
        title        = 'A Spoonful of Sugar',
        starting_npc = 'Southern San d\'Oria (S)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Using the key ingredient you and Lilisette have laboriously acquired, Amaura was finally able to concoct the same medicine that Sir Ragelise used all those years ago. Deliver it to the ailing knight at the Chateau d\'Oraguille without delay.',
        series       = 'Wings of the Goddess',
