    ['Back to the Beginning'] = {
        title        = 'Back to the Beginning',
        starting_npc = 'N/A',
        subtitle     = 'Cait Sith\'s Assistant',
        repeatable   = 'No',
        description  = 'Hideous statues. Monstrous beasts. The otherworld that lies in between. Could this war-torn land you have been thrust to truly be the outskirts of Jeuno...?',
        series       = 'Wings of the Goddess',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Pick up a recommendation letter from one of the three Allied fortresses near Jeuno: Garlaige Citadel (S), Crawlers\' Nest (S), or The Eldieme Necropolis (S).', sub = {
                { 'All three letters can be obtained, but you may only be allied to one nation at a time.' },
                { 'Allegiance has no impact on mission progression; quests are the same regardless of nation.' },
                { 'Your allied nation has cheaper Allied Notes items (50% markup at other nations) and determines Retrace / Instant Retrace destination.' },
            } },
            { '── Joining San d\'Oria ──' },
            { 'Speak with Randecque in Garlaige Citadel (S) at (I-6) on the second map.', sub = {
                { 'Zone in and follow the left wall at any intersection until reaching the Planar Rift (H-7).' },
                { 'Turn right at the Planar Rift, through the Heavy Iron Gate, then through a second Heavy Iron Gate until you reach Randecque.' },
            } },
            { 'Receive Key Item: Red recommendation letter and proceed to San d\'Oria.' },
            { '── Joining Windurst ──' },
            { 'Speak with Kalsu-Kalasu in Crawlers\' Nest (S) at (L-8), near the entrance.' },
            { 'Receive Key Item: Green recommendation letter and proceed to Windurst.' },
            { '── Joining Bastok ──' },
            { 'Speak with Turbulent Storm in The Eldieme Necropolis (S) at (J-9), near the entrance (enter from Batallia Downs (S) at (J-10)).' },
            { 'Receive Key Item: Blue recommendation letter and proceed to Bastok.' },
            { '── Delivering the Letter ──' },
            { 'Most maps appear the same as the present; new zone lines do not show.' },
            { 'San d\'Oria route — Batallia Downs (S) > northern Jugner Forest (S) > Vunkerl Inlet (S) > southern Jugner Forest (S) > East Ronfaure (S).' },
            { 'Windurst route — Sauromugue Champaign (S) > Meriphataud Mountains (S) > Fort Karugo-Narugo (S) > West Sarutabaruta (S).' },
            { 'Bastok route — Rolanberry Fields (S) > Pashhow Marshlands (S) > Grauberg (S) > North Gustaberg (S).' },
            { 'Vunkerl Inlet (S), Fort Karugo-Narugo (S), and Grauberg (S) maps are absent by default (30,000 gil from Magical Map Vendors in present, or 3,000 gil in past/Shadowreign for Fort Karugo-Narugo at minimum).', sub = {
                { 'Map quests: The Flipside of Things (Vunkerl), The Weekly Adventurer (Fort Karugo-Narugo), Lost in Translocation (Grauberg).' },
            } },
            { '── Follow-Up Quests: San d\'Oria ──' },
            { 'In Southern San d\'Oria (S), give Key Item: Red recommendation letter to Mainchelite at (I-9), next to the command post, and complete Steamed Rams.', sub = {
                { 'This declares your allegiance with San d\'Oria.' },
            } },
            { 'Complete Gifts of the Griffon, then Claws of the Griffon.' },
            { '── Follow-Up Quests: Windurst ──' },
            { 'In Windurst Waters (S), give Key Item: Green recommendation letter to Miah Riyuh at (H-9) and complete Snake on the Plains.', sub = {
                { 'This declares your allegiance with Windurst.' },
            } },
            { 'Complete The Tigress Stirs, then The Tigress Strikes.' },
            { '── Follow-Up Quests: Bastok ──' },
            { 'In Bastok Markets (S), give Key Item: Blue recommendation letter to Adelbrecht at (E-9), next to the command post, and complete The Fighting Fourth.', sub = {
                { 'This declares your allegiance with Bastok.' },
            } },
            { 'Complete Better Part of Valor, then Fires of Discontent.' },
            { '── Wrap Up ──' },
            { 'Once any single questline is complete, touch a Cavernous Maw outside Jeuno in the past for the Cait Sith (Mission) cutscene; receive the title "Cait Sith\'s Assistant".', sub = {
                { 'Present-day maws around Jeuno also work if previously unlocked.' },
                { 'Without unlocked maws, only the randomly-generated zone you landed in during the previous mission is available.' },
            } },
        },
    },
