    ['Daughter of a Knight'] = {
        title        = 'Daughter of a Knight',
        starting_npc = 'Jugner Forest (S)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Could the mystery object the Cait Siths were discussing be related in any way to the medicine Sir Ragelise used to take? The answer lies with Amaura, a resident of present-day Southern San d\'Oria.',
        series       = 'Wings of the Goddess',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Speak to Amaura in Southern San d\'Oria HP #4 at (G-6); she requests a Cernunnos Bulb.', sub = {
                { 'Fastest route: Home Point #4 for Southern San d\'Oria.' },
                { 'Kill Wandering Saplings in Jugner Forest (S) for a Cernunnos Bulb if you did not farm one already.' },
            } },
            { 'Trade the Cernunnos Bulb to Amaura for a cutscene.' },
            { 'Trade the Cernunnos Bulb to the Humus-rich Earth in Jugner Forest (S) at (E-6) to plant it.', sub = {
                { 'Fastest route: Campaign Arbiter warp, then ride a mount northwest.' },
                { 'Beware Lobison aggro in the area.' },
