}

quest_info['mkdmissions'] = {
    ['Kupo Mission 1'] = {
        title        = 'A Moogle Kupo d\'Etat',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'It all began with a raindrop, or so the legend says... Little did anyone suspect that this would prove to be only the beginning of a harrowing nightmare unheard of in the annals of mooglekind.',
        series       = 'A Kupo d\'Etat',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Zone into your Mog House and speak to your Moogle while at level 10 or above for a cutscene.', sub = {
                { 'Must be your home nation Mog House — the cutscene will not trigger in a rent-a-room.' },
            } },
        },
    },
    ['Kupo Mission 10'] = {
        title        = 'Roar! A Cat Burglar Bares Her Fangs',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'What\'s this!? Toto has enlisted the services of the formidable feline filcher Nanaa Mihgo to guard his prize catch! Can you declaw the Cat Burglar, or will you end up as cat food?',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'In the Chamber of Oracles, examine the Shimmering Circle to enter the battlefield.', sub = {
                { 'Home Point #1 is the fastest way.' },
            } },
            { 'Defeat Nanaa Mihgo in the battlefield.', sub = {
                { 'Normal melee attacks have a chance to add Paralyze, Stun, or Poison.' },
                { 'Uses normal Dagger weaponskills (Viper Bite, Wasp Sting, Dancing Edge, Evisceration) plus King Cobra Clamp — conal damage with Paralyze, Stun, and Poison.' },
                { 'Twice during the fight she summons either Bopa Greso or Cha Lebagta.' },
                { 'Accompanied by Goblin Repossessor (THF), Goblin Intimidator (WAR), and Goblin Enforcer (RDM).' },
            } },
            { '── Strategy ──' },
            { 'All mobs are susceptible to Sleep and Repose; sleep Nanaa Mihgo and pick off the goblins first.' },
            { 'You only need to defeat Nanaa Mihgo to complete the battlefield.' },
            { 'Trust Magic can be used in this battlefield.' },
            { 'On victory you receive a Key Item Red coral key, a cutscene plays, and the next mission begins.' },
        },
    },
    ['Kupo Mission 11'] = {
        title        = 'Relief! A Triumphant Return',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'The battle won and the fair maiden rescued, all is well for our plucky protagonists. What better time to return to the newly renovated Rent-a-Room for some much-deserved rest and relaxation...?',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Return to the Inconspicuous Door in Upper Jeuno at (H-8) (across from Durable Shields) for a cutscene that completes this mission and starts the next.' },
        },
    },
    ['Kupo Mission 13'] = {
        title        = 'A Challenge! You Could Be a Winner',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'A series of heart-stirring festival games, culminating in the purportedly profitable "Mega Mog Bonanza-Rama-Palooza"! Will our hero go home a champ, or a chump!?',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Examine the Shadowy Pillar at Castle Zvahl Baileys (J-8) — you will be directed to Beaucedine Glacier.', sub = {
                { 'Fastest way is to teleport with the Survival Guide.' },
            } },
            { 'Examine the Lonely Evergreen at the center of Beaucedine Glacier at (G-7) for a cutscene.' },
            { 'Go to the tower at (H-8) and speak to Goblin Grenadier.', sub = {
                { 'You need a Map of the Northlands area to advance through this part of the mission.' },
            } },
            { 'Enter a combination to open a chest, then speak to the Goblin Grenadier to guess the password (a number 0-9). You may accept up to 2 additional hints before guessing.', sub = {
                { 'Hints come from touching the 6 Pips in the area to spawn elemental NPCs. Do not leave the zone or it resets — markers are in the green markers option of the map.' },
                { 'Elementals form a pattern following the Vana\'diel week: Firesday > Earthsday > Watersday > Windsday > Iceday > Lightningday > Lightsday > Darksday.' },
                { '"Connect the dots" between pips whose days are next to each other to form the number (like writing a digit on an old alarm clock). Days loop (Fire-Dark connects). Connections are straight-across or up/down only — no diagonals. The order of the pips themselves does not matter.' },
                { 'Tip: draw 6 dots on paper in the pip layout, draw lines between adjacent-day pairs (and x\'s between non-adjacent pairs), then read the digit. Example: Water > Earth > Dark > Fire > Light > Lightning top-left to bottom-right = 2.' },
            } },
            { 'Open the chest to receive the Key Item Pocket mogbomb and a Flee status (+60% movement, 5 minutes) if you used no hints.' },
            { 'Return to the Lonely Evergreen at (G-7) to receive the Key Item Trivia Challenge Kupon.' },
            { 'In Xarcabard, locate three Option spots: Option One at (G/H-8), Option Two at (G-9), Option Three at (G-8). Answer three trivia questions correctly. Order of selection does not matter.', sub = {
                { 'Possible questions: HP+MP, Job level sum, Crafting skill sum (Synergy excluded), Elemental resistance sum, Total kills, Attack x Defense, Mog house entrances, Total deaths, Joined party, Joined alliance.' },
                { 'Each question gives 2 numeric options. Divide bigger by smaller: ratio ~2 means pick the bigger; ratio ~1.5 means pick the smaller. If one option is 0 (e.g. crafting), pick the 0.' },
            } },
            { 'On winning you receive the Key Item Gauntlet Challenge Kupon.' },
            { 'Zone into Castle Zvahl Baileys and speak to the Shadowy Pillar by the zoneline.', sub = {
                { 'Your level is lowered to 1 and you are granted Sneak, Invisible, and Deodorize. Durations are random (3-7 minutes) — bring Prism Powder and Silent Oil as backup.' },
                { 'You must reach the Flame of Fate within 8 minutes of the level cap.' },
                { 'Flame of Fate is just before the Castle Zvahl Keep zoneline; touching it grants the Key Item Festival Souvenir Kupon.' },
                { 'Directions: from the Shadowy Pillar, follow the path into the Baileys to the first intersection; take a right, then at the end go down the stairs, quick left then right, stay right to the map change at A on Map 1 (leads to Map 2). On Map 2, head straight north (ignore the early left/west turn), go up the left stairs when you see them, do not descend any holes or use the other stairs; head southwest around the first hole, cross the bridge west to another section with a hole, turn right/north down different stairs, take a right (stay lower), another right under the bridge you just crossed, first right past the bridge, then a left and another left to stairs back up; turn right toward the Castle Zvahl Keep exit. The Flame is in the Baileys on the floor below the last torch on the left at (G-8) — press left when targeting. Drop Invis to click it.' },
                { 'Do not go past the Flame of Fate and up the huge stairs into the next area, or you must walk back from the pillar.' },
            } },
            { 'Zone into Castle Zvahl Keep and speak to the Ominous Pillar by the zoneline before entering the large room ahead.', sub = {
                { 'You must find a slacking moogle by examining Craggy Pillars along the way to the Throne Room. Completing this grants the Key Item Mega Bonanza Kupon.' },
                { 'Craggy Pillars sit in each room directly after one of the beastmen-beacon teleporters. To reach the teleporter room, take exit A or B (through Iron Gates and Ore Doors) then exit C into Map 3. You may use the teleporters up to 4 times depending on the target room.' },
                { 'The 4th warp is the exception — the Craggy Pillar is in the next room to the south.' },
                { 'Inspect a pillar after each teleport; do not accidentally zone out, or you must walk back to the Ominous Pillar.' },
            } },
            { 'Continue teleporting if needed, approach and walk through the Throne Room, then examine the Throne Room door for a cutscene that completes the mission.' },
        },
    },
    ['Kupo Mission 14'] = {
        title        = 'Smash! A Malevolent Menace',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Lying in wait in the castle\'s innermost chambers was not a generous jackpot, but a chilling confrontation! With a malevolent moogle poised to unravel not merely Mog House tradition but the very fabric of the universe, only our heroes can stand in his way!',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Examine the Throne Room door to enter the BC.' },
            { 'Defeat Riko Kupenreich.', sub = {
                { 'Basic attacks are special bomb throws dealing conal AoE damage with knockback. Barfira reduces damage. Slow debuffs and Spikes have no effect.' },
                { 'Can teleport within the arena.' },
                { 'Fully resists Sleep. Susceptible to Stun.' },
            } },
            { '── Riko Weaponskills ──' },
            { 'Washtub — AoE 200-400 damage, absorbed by 3 Shadows.' },
            { 'Bill Toss — Terror.' },
            { 'Crystalline Flare — Draw-in and AoE 300-600 damage with Blind and Stun (~15 seconds).' },
            { '── Adds Phases ──' },
            { 'At 50% HP, Riko summons 5 Henchmen Moogle Black Mages at his location and 2 Henchmen Moogle White Mages on the throne dais and retreats.', sub = {
                { 'Black Mages are susceptible to sleep/lullaby and can be killed; cast Tier III -ga and Tier IV spells.' },
                { 'White Mages cannot be damaged or slept and repeatedly cast Cure V on Riko.' },
                { 'After Riko is fully healed or the Black Mages despawn, he returns to the battle.' },
            } },
            { 'A 2nd adds phase happens after losing another 50% health.' },
            { '3rd and final adds phase — Riko spawns Black Mages but does not retreat. Most dangerous phase: Crystalline Flare plus Black Mages simultaneously.' },
            { '── Moogle Henchmen Weaponskills ──' },
            { 'Mog Shrapnel — conal "Gil Toss" TP move, 20-200 damage, weak.' },
            { 'Mog Bomb — 200-400 fire damage, fairly weak.' },
            { 'Flowerpot — single-target Amnesia, Bind, and Stun.' },
            { '── Notes ──' },
            { 'Riko and his henchmen take increased damage from all sources but have very high HP.' },
            { 'On victory you receive a Key Item Angel skin key and a Key Item Oxblood key.' },
            { 'It is possible to skip phase 2 by killing Riko extremely fast at 119 gear levels. Trusts can be called if doing this before item level 119.' },
            { 'On defeat you must restart from Kupo Mission 13. You may re-attempt by returning to the Lonely Evergreen in Beaucedine Glacier — no need to start from the initial pillar in Castle Zvahl Baileys.' },
        },
    },
    ['Kupo Mission 15'] = {
        title        = 'A Moogle Kupo d\'Etat (Fin.)',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = '',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Head to Tenshodo in Lower Jeuno and examine the Treasure Chest for your reward.', sub = {
                { 'To repeat the fight and reroll augments: toss your augmented item, then buy the Key Item Mega Bonanza Kupon from Squintrox Dryeyes in Port Jeuno for 2,000 gil and 20 Beastmen Seals to re-enter the BCNM in the Throne Room. You cannot re-enter while still holding the Angel skin key — exchange it at the red chest in Lower Jeuno Tenshodo first.' },
                { 'There is a Japanese Midnight wait on immediately repeating the fight, otherwise: "Mega Bonanza Kupon has no effect. You cannot enter battlefield at present. Please wait a little longer."' },
            } },
            { 'After the fight you immediately receive your key rewards.' },
        },
    },
    ['Kupo Mission 2'] = {
        title        = 'Drenched! It Began with a Raindrop',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'With the ramshackle roof of your Mog House unable to withstand the elements, your moogle cohort entreats you to find three materials required for some much-needed renovations: an Orcish armor plate, a Quadav backscale, and a block of Yagudo caulk.',
        series       = 'A Kupo d\'Etat',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Trade the following three items to your Moogle, all at once, in the Mog House of your current nation of allegiance:', sub = {
                { 'Orc. Armor Plate — dropped from Orcs in Yughott Grotto.' },
                { 'Quadav Backscale — dropped from Quadavs in Palborough Mines.' },
                { 'Yagudo Caulk — dropped from Yagudos in Giddeus.' },
            } },
        },
    },
    ['Kupo Mission 3'] = {
        title        = 'Hasten! In a Jam in Jeuno?',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Word has it that the Rent-a-Room in Jeuno is also showing signs of spoilage. Unable to resist your moogle companion\'s earnest plea, you reluctantly agree to investigate the premises...',
        series       = 'A Kupo d\'Etat',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Examine the Inconspicuous Door in Upper Jeuno (H-8), across from Durable Shields, for a cutscene.' },
        },
    },
    ['Kupo Mission 4'] = {
        title        = 'Welcome! To My Decrepit Domicile',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'Yes',
        description  = 'Rotting roofboards, crumbling walls... Yes, this Rent-a-Room is a mess. Your moogle associate has the handyman skills; all he needs are a few essential items to make the requisite repairs.',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Obtain Key Item sturdy metal strip by mining in Gusgen Mines, Palborough Mines, or Ifrit\'s Cauldron.' },
            { 'Obtain Key Item piece of rugged tree bark by logging in East Ronfaure, Jugner Forest, or Ghelsba Outpost.' },
            { 'Obtain Key Item savory lamb roast by harvesting in Giddeus or West Sarutabaruta.' },
            { 'Examine the Inconspicuous Door in Upper Jeuno (H-8), across from Durable Shields, three times for three cutscenes.', sub = {
                { 'You do not need all three key items first; each one triggers one cutscene.' },
            } },
            { '── Notes ──' },
            { 'Key items can be obtained in any order, even before the moogle asks for them.' },
            { 'Keep your inventory full at the gathering node to allow repeated attempts on the same node.', sub = {
                { 'The node persists when gathered items can\'t be received, saving you from chasing new nodes.' },
                { 'Drops are truly random and have taken 50+ attempts for unlucky players. Bring at least 1 stack of each tool.' },
            } },
        },
    },
    ['Kupo Mission 5'] = {
        title        = 'Curses! A Horrifically Harrowing Hex',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'When a missive from Boss Kupeliaure unexpectedly unleashes a calamitous curse, our hard-luck heroes seek out the aid of the esteemed yet eccentric exorcist Professor Shantotto.',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Speak to Shantotto in Windurst Walls (K-7) for a cutscene. She asks for a Key Item Ripe starfruit, automatically starting the next mission.' },
        },
    },
    ['Kupo Mission 6'] = {
        title        = 'An Errand! The Professor\'s Price',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'The Professor consents to lend you her aid, but as expected, there\'s a price to be paid. Within a Cardian in the Outer Horutoto Ruins lies the reagent she does seek; return it to her, that you might avert a fate most bleak!',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Enter Outer Horutoto Ruins from West Sarutabaruta (F-11).' },
            { 'Defeat Cardians to obtain one or more Orb key items.', sub = {
                { 'Possible drops: Orb of Swords, Orb of Cups, Orb of Batons, Orb of Coins.' },
            } },
            { 'Zone into Outer Horutoto Ruins from East Sarutabaruta (H-3).' },
            { 'Examine the ??? on top of the platform at (H-6) to begin a battlefield.', sub = {
                { 'Trust Magic cannot be used in this battlefield.' },
                { 'Up to 15 Custom Cardians spawn and attack; the starter loses all possessed Orbs.' },
                { 'Orbs held by the starter remove damage-type immunities: Swords removes slashing, Batons removes blunt, Cups removes piercing, Coins removes magic.' },
                { 'Cardian count: 1-2 Orbs = 15 Cardians, 3 Orbs = 10 Cardians, all 4 Orbs = 5 Cardians.' },
                { 'Other party members with Orbs also lose them but receive no bonus.' },
                { 'Reward: 500 EXP, Key Item Ripe starfruit, Key Item Peach coral key.' },
            } },
            { 'Return to Shantotto and pay her 5000 gil.' },
            { 'Return to the Inconspicuous Door in Upper Jeuno (H-8), across from Durable Shields, for a cutscene.' },
        },
    },
    ['Kupo Mission 7'] = {
        title        = 'Shock! Arrant Abuse of Authority',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'When the linguistically challenged toady Toto Kupeliaure demands a ridiculous sum in unpaid rent, your moogle comrade chooses to make the ultimate sacrifice. Venture forth and unearth the moggy bank that contains his hard-earned wedding funds!',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Head to the Chocobo Digging zone mentioned by your moogle and dig up the Key Item Moldy, worm-eaten chest.', sub = {
                { 'You need Gysahl Greens to dig; bring at least a stack, more in some cases.' },
                { 'Each dig gives a direction hint and a proximity hint. "Immediate vicinity" means you are nearly on top of it.' },
            } },
            { 'Return to the Inconspicuous Door in Upper Jeuno (H-8), across from Durable Shields, for a cutscene.' },
        },
        notes        = {

            { 'Chocobo Digging proximity hints (coldest to hottest):', sub = {
                { '"Favored by moogles" — freezing cold.' },
                { '"Vague feeling... traversing this terrain" — very cold.' },
                { '"Scenery... to a moogle\'s liking" — cold.' },
                { '"Friend has been through this way" — warm.' },
                { '"Frequents this spot" — hot.' },
                { '"Digging in the immediate vicinity" — very hot.' },
            } },
        },
    },
    ['Kupo Mission 8'] = {
        title        = 'Lender Beware! Read the Fine Print',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Oh, woe! Having exhausted all other options, your star-crossed moogle associate is forced to seek aid from the shadiest of scoundrels. You have an appointment with the underworld moneylender Riko Kupenreich at his office in Sea Serpent Grotto.',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Travel to Sea Serpent Grotto and examine the Shady Sconce at (C-5) for a cutscene. May need two attempts to register.', sub = {
                { 'Norg is the closest teleport.' },
            } },
            { 'Use a Sahagin Key on the Ornamental Door at (J-11) in Sea Serpent Grotto.' },
            { 'Continue to Sea Serpent Grotto map 5 and examine the Waterfall Basin at (H-6) for a cutscene.' },
            { 'Return to the Inconspicuous Door in Upper Jeuno (H-8), across from Durable Shields.' },
        },
    },
    ['Kupo Mission 9'] = {
        title        = 'Rescue! A Moogle\'s Labor of Love',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'A dire development! Your moogle partner\'s betrothed, the fair Kupiruru, has been kidnapped by Toto\'s band of hoodlums! Make haste for the Chamber of Oracles to save the moogle maiden from a frightening fate!',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Make sure you possess the Key Item Map of the Quicksand Caves before starting (required).' },
            { 'Head to Western Altepa Desert (D-12), or use Geomagnetic Fount Waypoint, to reach Quicksand Caves map 5.', sub = {
                { 'Alternatively, use Quicksand Caves Home Point #1 for the Chamber of Oracles, then exit via exit 5 of map 5 at (H-4) to Western Altepa Desert and head south to (D-12).' },
            } },
            { 'Speak to the Goblin Geologist at (J-11). He asks you to gather 9 Stone key items from ??? spots in the Quicksand Caves.', sub = {
                { 'Stones: Surya, Chandra, Mangala, Budha, Brihaspati, Shukra, Shani, Rahu, Ketu.' },
                { 'The Goblin marks ??? locations on your map in the green Markers section. Map key item is required.' },
                { 'Markers are stored locally and randomized; finish in one session on the same PC, or back up your data.' },
                { 'Markers do not clear after collection — track which you have already done.' },
                { 'Use "Change Map" to check Markers on other maps and plan entrances.' },
            } },
            { '── ??? Entrances ──' },
            { 'Western Altepa Desert (G-5) — Entrance 6 to Quicksand Caves Map 5.' },
            { 'Western Altepa Desert (J-9) — Entrance 2 to Quicksand Caves Map 3 / Map 4.', sub = {
                { 'Map 4 is reached via (D-11) on Map 3, exit C.' },
            } },
            { 'Eastern Altepa Desert (K-7) — Entrance 1 to Quicksand Caves Map 1.' },
            { 'Eastern Altepa Desert (H-10) — Entrance 4 to Quicksand Caves Map 2.' },
            { 'These can require one-way drops; bring Teleport-Altep and Instant Warp to recover from mistakes.', sub = {
                { 'Quicksand Caves Home Point #2 is on Map 1 outside Cloister of Tremors near Exit 3 — grab it on the way if you don\'t have it.' },
            } },
            { 'Once all nine stones are collected, return to the Goblin Geologist to receive Key Item Navaratna talisman.' },
            { 'Enter the Chamber of Oracles and examine the Shimmering Circle for the completing cutscene.', sub = {
                { 'Quicksand Caves Home Point #1 is just outside the Chamber of Oracles — a great time to unlock it.' },
                { 'With Open Sesame\'s Key Item Loadstone (or as a Galka) you can solo the pressure pads; otherwise need 3 Tarutaru or a combo of 2 Hume/Elvaan/Mithra (Trusts don\'t count).' },
                { 'Path from Goblin Geologist: (I-9) weight pad through door, west to (H-7) weight pad through door, drop down the hole, head to (D-4) to zone to Chamber of Oracles.' },
            } },
        },
        notes        = {

            { 'None of the ??? require weight switches, but doing Open Sesame for Key Item Loadstone is convenient if you haven\'t attuned to Quicksand Caves Home Point #1 and #2.' },
        },
    },
}

quest_info['asamissions'] = {
    ['A Shantotto Ascension Mission 1'] = {
        title        = 'A Shantotto Ascension',
        starting_npc = 'Windurst Walls',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Doctor Shantotto returned to Windurst one day after a mysterious, unexplained absence, shocking her colleagues by proclaiming herself ruler of her own empire. What could have possibly triggered this intensification of her inimical urges? The shocking truth awaits adventurers who would seek it!',
        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Zone into Windurst Walls from Windurst Woods or Windurst Waters at level 10 or above.', sub = {
                { 'Entering via any other means (including Mog House) will not trigger the starting cutscene.' },
            } },
        },
    },
    ['A Shantotto Ascension Mission 10'] = {
        title        = 'Battaru Royale',
        starting_npc = 'Full Moon Fountain',
