        series       = 'None',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Receive 6 Domina\'s seal key items (scarlet, cerulean, emerald, amber, violet, azure) to attach to at least 3 Protocrystals around Vana\'diel.', sub = {
