    ['Seekers of Adoulin Mission 1-8'] = {
        title        = 'Arciela Appears Again',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: By reuniting with--and learning the identity of--Arciela V. Adoulin, you have set the wheel of fate in motion...',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Use Imprimaturs on Coalition Assignments and then speak to Levil in the Pioneers\' Coalition to complete this Mission and start the next.', sub = {
                { 'The Imprimatur requirement can be fulfilled prior to this Mission; the next Mission can then be started on the next game day.' },
                { '15 Imprimaturs utilized + Fame 2 (I\'m on a Boat / Hide and Go Peak / Western Waypoints, Ho! / Eastern Waypoints, Ho! / The Old Man and the Harpoon) is sufficient.' },
            } },
            { '── Quick Coalition Assignments ──' },
            { 'Inventors\' Coalition — farm/buy stacks of Bloodthread and repeat the Gather Materials: Rala Waterways Task.', sub = {
                { 'Accept the task, trade 3 Bloodthread to the Task Delegator, then talk to the Task Delegator again to finish. Repeat.' },
            } },
            { 'Couriers\' Coalition — do simple delivery assignments.', sub = {
                { 'Walk out to the waypoint, teleport to a bivouac and talk to the administrator for the delivery, then return to the Couriers\' guild.' },
            } },
            { '── Quick Repeatable-Quest Fame ──' },
            { 'Run the trio of repeatable item-turn-in quests.', sub = {
                { 'You may be able to find the turn-in items on the AH in sufficient quantities; setting your Home Point to HP#1 in Eastern Adoulin can help.' },
            } },
            { '── General Adoulin Quests ──' },
            { 'Complete Adoulin Quests to bolster your accomplishments in the area.' },
            { '── Going Forward ──' },
            { 'Continue using your Imprimaturs — higher requirements are needed for a future mission.' },
            { 'You can \'bank\' Imprimaturs by accepting assignments and cancelling them later (full refund on cancel).', sub = {
                { 'Inventors\' can be done fully with the AH, and Couriers\' can be done fully with waypoints.' },
            } },
            { 'Be diligent about ranking everything up to Legend if you want any of:', sub = {
                { 'Ergon Weapons (GEO\'s Idris & RUN\'s Epeolatry — very useful for those jobs).' },
                { 'The Golden shovel cordon, prerequisite for the Adoulin epilogue questline (upgrades your chosen scenario ring to +1 and grants a special healer trust).' },
            } },
        },
    },
