    ['Seekers of Adoulin Mission 2-2'] = {
        title        = 'An Aimless Journey',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Arciela was nowhere to be found at the castle, but one of her servants let slip that she was off to investigate an ergon locus in Cirdas Caverns. Has she really traveled out there alone...?',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Travel to Cirdas Caverns and head toward the Ergon Locus at (E-9) for a cutscene.', sub = {
                { 'The Ergon Locus is blocked by a Colonization Reive requiring "Logging".' },
            } },
            { 'After viewing the cutscene you can continue Tears of the Generals (Rhapsodies of Vanadiel Mission 3-6).' },
            { '── Suggested Routes to Cirdas Caverns ──' },
            { 'Minimal colonization reives and survival skills — Ceizak Battlegrounds WP #3 to southwest to Sih Gates to west to Cirdas Caverns (southeast corner; one lair reive along the way).' },
            { 'Less cave navigation — Foret de Hennetiel WP #3, clear the northern colonization reive to cross the water, to Dho Gates, one-way drop into Cirdas Caverns (southwest corner; no additional reives in Cirdas).' },
            { 'Quick if you\'ve been to Yorcia — from the Frontier Station there, back to the nearby entrance, cross the water, sneak+invis up, and clear reives as necessary.' },
            { 'If you\'ve unlocked the Augural Conveyor from a previous visit — use a waypoint to be teleported to (J-3) for 300 Units.' },
        },
        notes        = {

            { 'Choosing "Her glowing face." — Arciela: ...What\'s wrong? Is there something in my teeth?' },
            { 'Choosing "Her buxom bosom." — Arciela: ...Can I help you?' },
        },
    },
