    ['Seekers of Adoulin Mission 2-5-2'] = {
        title        = 'For Whom Do We Toil?',
        starting_npc = 'Levil, Western Adoulin (E-8)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: The only thing on Adoulinians\' lips these days seems to be that the city\'s youth are using the Rala Waterways without permission. Descend underground once more to see if this is actually the case.',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Enter Rala Waterways for a cutscene.', sub = {
                { 'Closest entrance is via Western Adoulin at (F-5) (closest to the Adoulin Waterfront Waypoint).' },
            } },
            { 'Proceed south to the dead end at (C-6), click the Sluice Gate, and enter the password (case-sensitive, all capitals) for a cutscene.', sub = {
                { 'Hint — the password is four letters, hinted on a marked page in the history book in the library and upon zoning into Rala Waterways.' },
                { 'Solution — the first initial of each order leader on the marked library page (the four who voted against the Colonization effort).' },
                { 'Password — HGSI (Hildebert, Gratzigg, Svenja, and Ikhi Askamot).' },
                { 'If you enter the wrong password too many times, you are locked out until you return to the library and read the History book again.' },
