    ['Seekers of Adoulin Mission 4-3'] = {
        title        = 'The Gates',
        starting_npc = 'N/A',
        subtitle     = 'Ulbukan Understudy',
        repeatable   = 'No',
        description  = 'Mission Orders: Chasing after Darrcuiln, you stumbled upon hordes of umbrils fighting leafkins. Who is the strange man fighting alongside the woodland creatures? Assist them in battle and find out the truth.',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Examine the Darkened Crevice at (G-8) in Woh Gates to enter "The Gates" BCNM against waves of Umbrils.', sub = {
                { 'May be attempted solo.' },
                { 'Battle starts automatically after about a minute, giving time to buff and call Trusts.' },
            } },
            { 'Defeat the Umbrils with NPC allies Arciela, Darrcuiln, Noble Warrior, and Resolute Leafkins.', sub = {
                { 'Arciela casts Haste, Protect V, and Shell V on herself, party, and NPCs.' },
                { 'Fight is lost if any NPC dies — NPCs can be buffed/healed with Blood Pact: Wards.' },
