    ['Seekers of Adoulin Mission 4-6'] = {
        title        = 'Balamor\'s Ruse',
        starting_npc = 'N/A',
        subtitle     = 'Shedder of Harlequin Tears',
        repeatable   = 'No',
        description  = 'Mission Orders: Ygnas was correct, and the evil clown was hiding in that tomb. A true enigma, Balamor has hidden statue segments in the monsters that roam the waterways and implores you to find them.',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Kill enemies in Rala Waterways until you acquire the Key Item Consummate simulacrum.', sub = {
                { 'Drop rate seems higher from Waterway Pugils and New Moon Bats; Efts/Diremites near the Augural Conveyor reportedly slower.' },
                { 'All party members in zone on the mission receive the Key Item simultaneously; previous completers can still cause it to drop.' },
                { 'The Key Item appears in Temporary Key Items after Wildskeeper Reive items but before high-tier mission battlefield entry items; a chat log message is shown but easy to miss.' },
            } },
            { 'Examine the Augural Conveyor at (B-6) in Rala Waterways, near the Western Adoulin Waterfront zone line at (F-5).', sub = {
                { 'No initial cutscene — choosing "The Charlatan" enters the battle immediately.' },
            } },
            { 'Defeat Balamor in a battle against him and three Dullahan.', sub = {
                { 'Only the party leader loses their Key Item Consummate simulacrum on entry; only the leader refarms on failure.' },
                { 'All party members who haven\'t previously completed must possess the Key Item to enter.' },
                { 'Arciela assists and can hold her own; battle is lost if she falls.' },
                { 'Trust Magic can be summoned inside.' },
                { 'All of Balamor\'s regular attacks appear to be AoE.' },
                { 'Regicidal Dullahan always targets Arciela and cannot be pulled; Balamor and his two Sycophants share hate.' },
                { 'Only Balamor needs to be defeated; he surrenders around 20% HP.' },
            } },
            { 'After clearing, you do not need another Key Item to re-enter the battlefield.' },
            { 'You are returned to the Royal Sepulcher; the nearby Eastern Adoulin exit is not usable, so warp out to reach the castle gate for the next mission.' },
        },
