    ['Seekers of Adoulin Mission 5-2'] = {
        title        = 'Yggdrasil Beckons',
        starting_npc = 'N/A',
        subtitle     = 'Vanquisher of Dhokmak Vanquisher of Ashrakk',
        repeatable   = 'No',
        description  = 'Mission Orders: Rosulatia has bequeathed upon you the ability to conquer Dhokmak and Ashrakk. Head with Morimar and Darrcuiln to Cirdas Caverns and Yorcia Weald and do just that.',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Complete the two BCNM fights below in either order; win each by reducing the primary target to 10% HP.', sub = {
                { 'Drawing your weapon immediately starts each battle regardless of distance to the enemy.' },
                { 'If you fail either battle, return to Leafallia and examine the Aged Stump at (H-8) to reacquire the Key Item required for entry.' },
            } },
            { '── Dhokmak ──' },
            { 'Head to (K-11) in Cirdas Caverns.', sub = {
                { 'Fastest: Waypoint -> Yorcia Weald Frontier Station -> west tunnel into Cirdas Caverns (requires Watercraft and Climbing).' },
                { 'Alt: Waypoint -> Enigmatic Device -> Cirdas Caverns.' },
                { 'Cheap/fast: Home Point Ceizak Battlegrounds -> mount to #2 -> waypoint to #3 (2 units) -> west to Sih Gates (E-10) -> west to Cirdas Caverns (C/D-5) -> southeast Cirdas entrance (L-13) -> (K-11).' },
            } },
            { 'Examine the Wavering Flux for a short cutscene, then examine it again to enter Cirdas Caverns (U).', sub = {
                { 'Party is warped in regardless of their location in the zone.' },
            } },
            { 'Defeat Dhokmak (and 3 Malignant Acuex).', sub = {
                { 'Darrcuiln assists; battle is lost if he falls.' },
                { 'Acuex minions can be slept but are usually woken by Darrcuiln\'s frontal cleaves.' },
                { 'Dhokmak has roughly 100k HP and is defeated at under 10%.' },
                { 'Receive Key Item Dhokmak\'s blood sigil and title "Vanquisher of Dhokmak".' },
            } },
            { '── Ashrakk ──' },
            { 'Head to the southeastern section of (H-6) in Yorcia Weald near the Colonization Reive.', sub = {
                { 'Fastest: Waypoint -> Yorcia Weald Frontier Bivouac #1, then southeast to (H-6).' },
            } },
            { 'Examine the Wavering Flux for a short cutscene, then examine it again to enter Yorcia Weald (U).' },
            { 'Defeat Ashrakk.', sub = {
                { 'Summons a Hell-spawned Orthrus below 50%; the Orthrus has moderately high HP for a minion.' },
                { 'Ashrakk can be killed directly while ignoring the minion with enough DPS.' },
                { 'Morimar assists; battle is lost if he falls.' },
                { 'Ashrakk has roughly 100k HP and is defeated at under 10%.' },
                { 'Has 3 melee attack types: single-target 3-hit, frontal cleave with added Shock, and single-target knockback.' },
                { 'Receive Key Item Ashrakk\'s blood sigil and title "Vanquisher of Ashrakk".' },
            } },
            { '── Notes ──' },
            { 'Repeating either battle to assist someone else yields 20,000 Bayld per fight.' },
        },
    },
