    ['The Ygnas Directive'] = {
        title        = 'The Ygnas Directive',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = '',
        series       = '',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Speak to Ploh Trishbahk at (K-9) after obtaining the Golden Shovel Cordon key item for a short cutscene to begin the quest.', sub = {
                { 'This quest is run through Records of Eminence and does not appear in the normal quest log.' },
                { 'Obtaining the Golden Shovel grants the title Contributer from the Shadows.' },
            } },
            { '── Objective 1 ──' },
            { 'Set the The Ygnas Directive 1 RoE Objective (Quests > Objective List > Other > RoE Quests 2).' },
            { 'Travel to Rala Waterways and speak to Chalvava at (F-11) for a cutscene.', sub = {
                { 'Best entry is from Western Adoulin near the Mog House at (I/J-12).' },
            } },
            { 'Return to Ploh Trishbahk for a cutscene completing Objective 1 and opening Objective 2.' },
            { '── Objective 2 ──' },
            { 'Set the The Ygnas Directive 2 RoE Objective.' },
            { 'Examine the Mischief Marker in Western Adoulin at (J-11) for a cutscene with Tuffle-Buffle and Musto-Rusto.', sub = {
                { 'Best entry is from the Inventor\'s Coalition or Mog House warps.' },
            } },
            { 'Speak to Virsaint at (H-8) near the Platea Triumphus for a cutscene.' },
            { 'Return to Ploh Trishbahk for a cutscene completing Objective 2.' },
            { 'Wait one game day and speak to Ploh Trishbahk again to open Objective 3.' },
            { '── Objective 3 ──' },
            { 'Set the The Ygnas Directive 3 RoE Objective.' },
            { 'Speak to Roskin near the Statue of the Goddess for a cutscene where he asks for Copse Candy.', sub = {
                { 'Copse Candy costs 10,000 bayld from Runje Desaali after unlocking; she initially offers it for 100,000 bayld.' },
                { 'Decline her offer; she will then sell it for 10,000 bayld in exchange for a Jungle Nectar (sold by Soupox in Leafallia).' },
                { 'You may need to ask Runje "What\'s up with the leafkin" to trigger the CS.' },
                { 'Copse Candy obtained through Login Campaign will be stolen in a cutscene until you fetch the nectar for Runje.' },
            } },
            { 'Trade Roskin the Copse Candy for a cutscene.', sub = {
                { 'Multiple candies may be needed because there is a chance for the candy to be stolen.' },
            } },
            { 'Return to Ploh Trishbahk for a cutscene completing Objective 3, rewarding Delegate\'s Cuffs, and opening Objective 4.' },
            { '── Objective 4 ──' },
            { 'Set the The Ygnas Directive 4 RoE Objective.' },
            { 'Speak to Levil in the Pioneer\'s Coalition for a cutscene.', sub = {
                { 'Speaking to Yocile at the Cafe des Larmes first redirects you to the Mummer\'s Coalition; Levil must still be spoken to.' },
                { 'If the Levil CS is blocked by another quest about Arciela and Kamihr Drifts, speak to Ploh Trishbahk first.' },
            } },
            { 'Speak to Masad in the Mummer\'s Coalition for a cutscene.' },
            { 'Beat Ygnas in Boom or Bust by winning 3 rounds. If you lose, speak twice to Masad to retry.', sub = {
                { 'Purchasing the Grunt Heard \'Round the World key item from Runje Desaali for 30,000 Bayld guarantees victory (unlocks after 3 lost matches / 9 losses).' },
                { 'Suggested tactic: keep shooting until you bust hoping for a 5 or 6; Ygnas typically stays around 10 or 11 and uses a trick first, then you can trick a high card onto him to bust him.' },
                { 'Easiest path: roll once and stay 9 times to farm losses, buy the key item from Runje Desaali, return to Masad and roll once then stay 3 times to win.' },
            } },
            { '── Boom or Bust Rules ──' },
            { 'Shoot — increase your roll like a Corsair Phantom Roll; over 11 busts.' },
            { 'Stay — close the round for yourself; both players staying ends the round and whoever is closest to 11 wins.' },
            { 'Trick — one per round.', sub = {
                { 'Peek — look at one of the opponent\'s rolls (cannot swap or use crooked after).' },
                { 'Swap — exchange one of your rolls for one of the opponent\'s.' },
                { 'Crooked Cards — force opponent to reroll a roll of your choice.' },
            } },
            { 'Fold — end the round in a loss.' },
            { 'Return to Ploh Trishbahk for a cutscene completing Objective 4 and rewarding Delegate\'s Garb.' },
            { 'Wait one game day and speak to Ploh Trishbahk to open Objective 5.' },
            { '── Objective 5 ──' },
            { 'Set the The Ygnas Directive 5 RoE Objective.' },
            { 'Examine the Door: Amuchuchu\'s Laboratory at the back of the Inventors\' Coalition in Western Adoulin (J-10) for a cutscene.' },
            { 'Examine the Contemplation Site at (I-5) in Western Adoulin beside the Adoulin Waterfront waypoint.' },
            { 'Examine the ??? in Yorcia Weald at (I-7/8) near the Ergon Locus, NW from the Frontier Station, for a cutscene.', sub = {
                { 'Wait until the flash-and-smoke animation, then hit Enter immediately as it explodes.' },
                { 'Set framerate to 30 fps to see the smoke animation correctly.' },
                { 'Failing immediately allows a retry without leaving the cutscene; a timer appears in the upper left after several failures (press Enter at 0:00).' },
            } },
            { 'Return to Ploh Trishbahk for a cutscene completing Objective 5, rewarding 20 Pinches of High-Purity Bayld, and opening Objective 6.' },
            { '── Objective 6 ──' },
            { 'Set the The Ygnas Directive 6 RoE Objective.' },
            { 'Speak to Zaffeld at (K-8) near the castle in Eastern Adoulin for a cutscene.' },
            { 'Examine the Occultist Footprints in Yorcia Weald at (J-6) (south-west corner, NW from the Frontier Station) for a cutscene.', sub = {
                { 'The footprints are just below the middle of the I-J/6 zone line.' },
            } },
            { 'Examine the footprints again to enter the BCNM vs. The Velkk King Gramk-Droog and his 5 Velkk generals from Incursion.', sub = {
                { 'Trusts may be called once inside; party with others who have completed or are on this objective.' },
                { 'You fight alongside Ygnas and Nashu; if either dies you lose. They have very high HP/MP and are durable.' },
                { 'Ygnas casts Protectra V, Shellra V, haste, erase, and cures.' },
                { 'Ygnas focuses one target at a time; assist him (/as <t>).' },
                { 'Sleep is highly recommended; NMs resist light-based sleeps but are susceptible to dark-based sleeps. Nashu casts Banishga II which wakes slept mobs; Liij-Vok Waaxwane\'s Benediction also wakes foes.' },
                { 'Velkk use their 1-hour abilities and Incursion TP moves: Jungle Wallop (AoE damage, Silence, Bind, Amnesia) and Jungle Hoodoo (Earth damage, Paralyze, Plague, -50% Curse).' },
                { 'Take care with Durs-Vike Deathspell — his Meteor is rapidly cast and tears through Trusts.' },
                { 'Velkk have roughly 50-80k HP each.' },
                { 'A tank trust generating AoE enmity (Amchuchu) or casting cures and JAs (August) helps hold hate when foes wake.' },
            } },
            { 'Return to Ploh Trishbahk for a cutscene completing Objective 6, rewarding 30 Pinches of High-Purity Bayld, and granting Ygnas\'s insignia.' },
            { '── Ring Reforging ──' },
            { 'While holding Ygnas\'s insignia, speak to Runje Desaali in Eastern Adoulin (J-10) to reforge your Adoulin Scenario-Reward Ring for 100 Pinches of High-Purity Bayld.' },
            { 'To exchange your HQ Ring for another, first trade Ploh Trishbahk your current HQ ring with 300,000 Bayld, then take the new NQ ring and 100 High-Purity Bayld to Runje Desaali.' },
        },
    },
