        next         = '',
        walkthrough  = {

            { 'Examine the Drifting Feather at (H-7) in Leafallia for a short cutscene to begin the quest.' },
            { 'Venture to the crag closest to your home nation and examine the Ergon Locus ??? beneath the Telepoint stairs to obtain Fistful of familiar soil.', sub = {
                { 'Cannot be obtained while possessing Holla crystal of gales, Dem crystal of dunes, or Mea crystal of flames from Treasures of the Earth of the same type (e.g. Holla crystal blocks the Crag of Holla ???).' },
            } },
            { 'Return to the Drifting Feather and examine it to enter a BCNM vs. Siren Prime.', sub = {
                { 'Content Level 119; Trusts allowed.' },
            } },
            { 'Defeat Siren and choose your reward in the cutscene.', sub = {
                { 'Repeatable once per Earth day, resetting at midnight in Japan.' },
            } },
        },
    },
}

