    ['Rhapsodies of Vanadiel Mission 1-14'] = {
        title        = 'The Ties that Bind',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Ill tidings abound. Something is causing sailors to take leave of their senses, with a strange ringing reminding you of what occurred in Escha - Zi\'Tah. See what is happening in Sea Serpent Grotto.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Head to Sea Serpent Grotto and examine the sparkling ??? near the lake at (J-12) for a cutscene.' },
            { '── Route A: From Norg ──' },
            { 'Exit Norg on foot (not chocobo) to the South (H-10), entering Sea Serpent Grotto at Map 1 (F-1).' },
            { 'Follow the tunnel southward to an apparent dead end near a torch at (H-6).', sub = {
                { 'There\'s a hidden door here with a blank target label that is always unlocked; this is usually the entrance you\'d need to find when getting into Norg traditionally.' },
            } },
            { 'Take an immediate left to go north-east to (J-5), then a right (southward) to the one-way drop down at (K-7).' },
            { 'Hug the left wall forward, ignoring the Ornamented Door (J-10), and proceed down the left tunnel until you reach a large room at (K-11).' },
            { 'The sparkling ??? is right in front of you on the edge of the water at (J-12).' },
            { '── Route B: Unity Warp ──' },
            { 'Use Unity Warp 125 for Sea Serpent Grotto to reach the zone.', sub = {
                { 'Sneak in advance — Mousse aggro to sound even at level 75+ and spawn along the route.' },
            } },
            { 'You arrive on Map 4 just past the "Gold Door" (blank when targeted); head back northeast toward it.' },
            { 'Target/tab to find the blank-labelled door at (M-5) and proceed; you re-enter Map 1 at (I-14).', sub = {
                { 'Coming from the outside you\'d need a Gold Beastcoin, but from inside no trade is needed.' },
                { 'Interacting from the outside 6 times yields a message about "something gold glittering" around the small indentation in the wall.' },
            } },
            { 'Once through, the lake is directly ahead — run around the northeast side to check the ??? at (J-12).' },
            { '── Post-Cutscene ──' },
            { 'Before warping, consider walking to the next mission\'s location. The return-route one-way tunnel is at (H-8); at the Cracked Wall blank-targetable door at (H-6) you can either:' },
            { 'Continue to Norg to rent a chocobo from Marilleune just right of the entrance.', sub = {
                { 'Puts you at (F-11), same as a Unity warp.' },
            } },
            { 'Take a right and hug the left wall to pick up the Survival Guide at (M-3) of Sea Serpent Grotto.', sub = {
                { 'Escape brings you here too, at (E-11).' },
                { 'From here, a mount takes a little over 30 seconds through the tunnel to the next destination.' },
            } },
        },
    },
    ['Rhapsodies of Vanadiel Mission 1-15'] = {
        title        = 'Impurity',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: The great Siren is the cause of the recent disturbances plaguing Norg, and she claims that Iroha was not the only one who came to the present time from the future. The masked man attacked Iroha, who faded into nothingness. Chase after him.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Go to (F-11) in Yuhtunga Jungle and examine the sparkling ??? for a cutscene.', sub = {
                { 'From Sea Serpent Grotto: a Black Mage can Escape the party straight out to Yuhtunga Jungle; without Escape, a short walk to the exit works.' },
                { 'From Norg: rent a Chocobo from Marilleune (H-9) near the exit to Sea Serpent Grotto and ride to the ???.' },
                { 'From elsewhere: use the Level 119 Unity Wanted teleport to Yuhtunga Jungle.' },
            } },
            { 'Solo players should reach at least level 80 before the next mission, as the fight may be harder than expected.' },
        },
    },
    ['Rhapsodies of Vanadiel Mission 1-16'] = {
        title        = 'The Lost Avatar',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Siren and the masked man attempted to conjure forth another vortex in Yuhtunga Jungle in a bid to cause Escha to spread further. Fight the winged beast and stop her before it\'s too late.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Note: the following fight is considerably more difficult than the content leading up to it. Solo (with trusts), reach at least level 80 before attempting.' },
            { 'Examine the ??? again to start the battle against Siren.', sub = {
                { 'Siren despawns after about 15 minutes, ending the fight without credit.' },
                { 'Can Charm, which despawns your trusts if it hits you — let a trust tank her (Item Level 119 players should solo even if charmed).' },
                { 'Uses Massacre Elegy and Wind Threnody II.' },
                { 'Absorbs Wind Elemental damage, including from Skillchains such as Detonation or Fragmentation.' },
                { 'Take care with Trusts like Cipher: Shantotto II — their AI targets the foe\'s greatest elemental weakness, but on full-absorb foes it heals them.' },
