    ['Rhapsodies of Vanadiel Mission 2-13'] = {
        title        = 'From the Ruins',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Alexander aided Phoenix in reviving Iroha. He knows much about the encroaching darkness, revealing that it\'s something far more sinister than the absence of light. Iroha has been brought back to Aht Urhgan to recover, where she and Aphmau await.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Return to Aht Urhgan Whitegate and click the Imperial Whitegate (the Palace Door) for a cutscene and Key Item: Rhapsody in Crimson.' },
            { '── Optional: Locate Alternate Sources of Darkness ──' },
            { 'These can be done any time during RoV Chapter 2, before Mission 2-39.' },
            { 'Alzadaal Undersea Ruins — requires all Aht Urhgan Missions completed.', sub = {
                { 'Re-enter Alzadaal Undersea Ruins for a cutscene.' },
            } },
            { 'The Shrouded Maw — requires Promathia Mission 3-5 (Darkness Named) completed.', sub = {
                { 'Zone into The Shrouded Maw via Pso\'Xja home point #1 or from Beaucedine Glacier (H-8) next to the Survival Guide.' },
            } },
            { 'The Garden of Ru\'Hmet — requires all Promathia Missions completed.', sub = {
                { 'Use The Garden of Ru\'Hmet home point #1, or talk to Sueleen in the Sealion\'s Den, then enter through the palace. Descend to the bottom level and enter the next area for a cutscene.' },
            } },
        },
    },
    ['Rhapsodies of Vanadiel Mission 2-14'] = {
        title        = 'Cauterize',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: The world has rejected Iroha\'s presence, but Alexander believes Cait Sith might have an answer. Cavernous maws in either Batallia Downs, Rolanberry Fields, or Sauromugue Champaign may enable you to meet with the enigmatic feline.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Head to a Cavernous Maw in Batallia Downs, Rolanberry Fields, or Sauromugue Champaign and click the sparkling ??? for a cutscene.', sub = {
                { 'May require being on at least Wings of the Goddess Mission 8: In the Name of the Father (verification needed).' },
                { 'See Ganged Up On for mission/quest progress that can block this cutscene.' },
                { 'Complete Champion of the Dawn and A Forbidden Reunion first if they are flagged.' },
            } },
            { 'If you have not started Wings of the Goddess, the mission line continues to Uncertain Destinations.' },
            { 'If you have started Wings of the Goddess, the mission line continues to Ganged Up On.' },
        },
    },
    ['Rhapsodies of Vanadiel Mission 2-15'] = {
        title        = 'Uncertain Destinations',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Cait Sith gave you a special item used to enter the Walk of Echoes after hearing your explanation about what may come to pass. Enter the Walk of Echoes from either Batallia Downs, Rolanberry Fields, or Sauromugue Champaign.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Examine the ??? next to a Cavernous Maw in Batallia Downs, Rolanberry Fields, or Sauromugue Champaign for a cutscene.', sub = {
                { 'Use the sparkling blue ???, not the white one.' },
            } },
        },
    },
    ['Rhapsodies of Vanadiel Mission 2-16'] = {
        title        = 'Ganged Up On',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Only Altana can make Vana\'diel accept Iroha\'s presence in this world, and the first step to reaching her is to cull the threats that Vana\'diel faces. Continue with the Wings of the Goddess missions if you have not met Lilisette.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {

            { '── If All Wings of the Goddess Missions Are Complete ──' },
            { 'Examine the ??? next to a Cavernous Maw in Batallia Downs, Rolanberry Fields, or Sauromugue Champaign for a cutscene.' },
            { '── If Wings of the Goddess Is Not Complete ──' },
            { 'You must be on or past Wings of the Goddess Mission 8: In the Name of the Father to progress.' },
            { 'Zone into Southern San d\'Oria (S) (via Home Point, Survival Guide, Retrace, or Instant Retrace) for a cutscene and Key Item: Lightsworm.', sub = {
                { 'You may already have the Lightsworm Key Item from previous quests — check first.' },
                { 'If the cutscene does not trigger, first click the sparkling blue ??? next to a Cavernous Maw in Batallia Downs, Rolanberry Fields, or Sauromugue Champaign, then return to Southern San d\'Oria (S).' },
                { 'If still not progressing to Sacrifice, talk to the Mystic Retriever in Southern San d\'Oria (S) at (M-6).' },
            } },
            { 'You will then be on Rhapsodies of Vanadiel Mission 2-17.' },
            { '── Notes ──' },
            { 'Lilisette is unavailable while on these Wings of the Goddess missions: On Thin Ice, Proof of Valor, A Sanguinary Prelude, Dungeons and Dancers, Distorter of Time, The Will of the World, Adieu Lilisette, By the Fading Light, Edge of Existence, Her Memories, Forget Me Not, Pillar of Hope, Glimmer of Life, Time Slips Away, When Wills Collide, Whispers of Dawn, Where It All Began*, A Token of Troth*, Lest We Forget*.' },
            { 'If you started Where It All Began by completing Maiden of the Dusk, you must finish the Wings of the Goddess storyline, Champion of the Dawn, and A Forbidden Reunion to continue.' },
            { 'If stuck without a Lightsworm: visit the Goblin Footprint in Batallia Downs (S) at (F-9), watch all Ganged Up On cutscenes, wait a game day, then check the shimmering ??? next to any present-day Maw in Rolanberry Fields, Sauromugue Champaign, or Batallia Downs.' },
            { 'Success message: "The bonds tying you to Altana have strengthened, enabling you to experience all the memories of Wings of the Goddess!"' },
            { 'If missing Cipher: Lilisette II, retrieve it from the Mystic Retriever in Southern San d\'Oria (S) at (M-6) near the Mog House.' },
        },
    },
    ['Rhapsodies of Vanadiel Mission 2-17'] = {
        title        = 'Sacrifice',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Though you have met Lilisette, she has no idea how to meet Altana. On the bright side, your orb has been granted another spark of light. Cait Sith has beseeched you for aid, saying that the ambassador has infiltrated the Walk of Echoes.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {

            { '── If on or past WotG Mission 45: Time Slips Away ──' },
            { 'Enter Walk of Echoes from Pashhow Marshlands (S) (J-9) or Grauberg (S) (F-5) and examine the Ornate Door.' },
            { '── Otherwise (at least on WotG Mission 8: In the Name of the Father) ──' },
            { 'Enter Walk of Echoes by touching the glowing ??? next to a Cavernous Maw outside Jeuno (uses Key Item: Lightsworm).', sub = {
                { 'Batallia Downs (H-5).' },
                { 'Rolanberry Fields (H-6) — Survival Guide to Rolanberry Fields is closest.' },
                { 'Sauromugue Champaign (K-9).' },
            } },
            { 'Run straight ahead after zoning in, up the stairs, and examine the Ornate Door.' },
            { 'Bring a warp (Warp Ring or Instant Warp) — the next mission leaves no fast way back to town.' },
        },
        notes        = {

            { 'May be continued from inside after entering for Ganged Up On.', sub = {
                { 'If you leave, you must re-enter Walk of Echoes from Grauberg (S).' },
            } },
            { 'Earliest you can do this mission is on Wings of the Goddess Mission 8: In the Name of the Father.' },
            { 'Players have reported getting stuck if on a different WotG mission; resume after completing A Dreamy Interlude.' },
            { 'Entering via the Xarcabard (S) Walk of Echoes entrance gives the cutscene but places you in the wrong instance — you cannot reach the Ornate Door. Use a Cavernous Maw outside Jeuno instead.' },
        },
    },
    ['Rhapsodies of Vanadiel Mission 2-18'] = {
        title        = 'Somber Dreams',
        starting_npc = 'N/A',
        subtitle     = 'Abyssal Purveyor',
        repeatable   = 'No',
        description  = 'Mission Orders: The ambassador threatens to absorb dark energy from Atomos and must be stopped. His minion Cetus has swallowed you whole--vanquish him before proceeding.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'You begin this mission in Grauberg (S)\'s Witchfire Glen after the previous cutscene.', sub = {
                { 'Helpers can use the Walk of Echoes Veridical Conflux to teleport to Witchfire Glen, but cannot use the ??? for a return trip at the end of this mission.' },
            } },
            { 'Examine the blue glowing ??? closest to your spawn point in Grauberg (S) to spawn Cetus.', sub = {
                { 'The correct ??? is NE of the Veridical Conflux, not the one right beside it.' },
                { 'Cetus gains Dread Spikes after Aetheric Pull — beware in older gear.' },
            } },
            { 'Defeat Cetus, then re-examine the ??? for a cutscene.' },
            { 'Re-enter Walk of Echoes for a cutscene by clicking the ??? beside the Veridical Conflux.' },
            { 'Warp back into town if you brought one.' },
        },
        notes        = {

            { 'This fight is intended for level 99; below 99 you may die.', sub = {
                { 'Solo with Trusts is possible in the early 90s with difficulty.' },
            } },
            { 'If you wipe, you cannot re-enter via the ??? beside a Cavernous Maw — you must walk to Grauberg (S) manually.', sub = {
                { 'Without a Survival Guide direct to Pashhow Marshlands (S) or North Gustaberg (S):' },
                { 'Rolanberry Fields (S) Survival Guide: use it, then follow the route below.' },
                { 'Otherwise: Survival Guide to Vunkerl Inlet (S), make your way to (H-11), drop at (I-11) toward (J-12) zoning into Rolanberry Fields (S).' },
                { 'Head down to (I-14), grab the Survival Guide, and zone into Pashhow Marshlands (S).' },
                { 'Pashhow Marshlands (S) layout matches present (Konschtat Highlands barricaded off). Head to (G-10), hug left to (G-11) for the Grauberg (S) zone line.' },
            } },
            { 'To respawn Cetus, head to (F-5) — (G/H-6) is a one-way drop, so take the long way.' },
            { 'Touch the ??? again for a quick cutscene.' },
            { 'Return to Walk of Echoes for a cutscene.', sub = {
                { 'To get the final cutscene, you must be on a Wings of the Goddess mission where Lilisette is available.' },
            } },
        },
    },
    ['Rhapsodies of Vanadiel Mission 2-19'] = {
        title        = 'Of Light and Darkness',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
