    ['Rhapsodies of Vanadiel Mission 2-35'] = {
        title        = 'Eddies of Despair',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Cid and his team have headed to Escha - Ru\'Aun, where a vortex is sucking up the crystals\' power. What lies beyond? Be on your guard as you proceed.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Upon entering Escha - Ru\'Aun, examine the ??? next to Dremi for an Eschan Droplet, then use the Eschan Portal to advance.' },
            { 'At each portal, find the ??? to get another Eschan Droplet, then teleport onward. Repeat to Portal #15.' },
            { '── Eschan Portal ??? Locations ──' },
            { 'Portal #2 — End of the only path, next to the door (not the one in front of the teleport).' },
            { 'Portal #3 — Up the first staircase near the pillar to the right.' },
            { 'Portal #4 — Across the bridge, between the two large pillars to the left.' },
            { 'Portal #5 — End of the only path, next to the door (not the one in front of the teleport).' },
            { 'Portal #6 — Southern (G-6), past and underneath the second staircase, on the bridge with the closed door.' },
            { 'Portal #7 — (F-5), directly left of the second bridge.' },
            { 'Portal #8 — End of the only path.' },
            { 'Portal #9 — Up both sets of stairs, turn left, left again at the bridge crossing the water; the ??? is in the middle of this area.', sub = {
                { 'Gargoyles aggro at night if you walk too close to their alcoves.' },
            } },
            { 'Portal #10 — Across both bridges, at the south-west side of the last platform.' },
            { 'Portal #11 — End of the only path.' },
            { 'Portal #12 — Sneak up, proceed up both sets of stairs, turn right, run past the staircase on the left; the ??? is past the staircase at (J-7).' },
            { 'Portal #13 — Across the first bridge, next to the first large pillar on the left.' },
            { 'Portal #14 — End of the only path.', sub = {
                { 'This process can be completed any time after gaining access to the zone.' },
                { 'If stuck on an island, return to the start for a fresh Eschan Droplet, pay silt for the Eschan Portal, and continue unlocking.' },
            } },
            { 'Click the shining ??? at Portal #15 for a cutscene.' },
            { '── Hpemde Tips ──' },
            { 'Think of them like flowers: closed are buds, open shows all pedals.' },
            { 'Sneak up since open and closed are randomly mixed.' },
            { 'Hpemde will not attack but will follow you like puppies if they hear you.' },
        },
    },
