    ['Rhapsodies of Vanadiel Mission 3-1'] = {
        title        = 'Darkness Beckons',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: The ambassador\'s plan is more sinister than imagined. He infused your soul with darkness in an attempt to hinder you. Yet you have been left with a tiny song of hope--what could it mean?',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Travel to the Crag of Holla, Dem, or Mea and examine the Dimensional Portal to travel to Reisenjima.', sub = {
                { 'Most mobs in Reisenjima will aggro; some have True Sight or True Sound.' },
                { 'Upon arrival, you will receive a brief cutscene.' },
            } },
            { 'Speak with Shiftrix the goblin by the entrance to activate the Oseem augmentation system.', sub = {
                { 'You don\'t need to pay for info.' },
                { 'He sells the Key Item Map of Reisenjima (50 Silt).' },
                { 'Consider grabbing a Key Item Mollifier (500 Silt) for the next Mission.' },
                { 'If you\'re doing missions just for the Dark Matter Arcane Glyphics Campaign, you may stop here.' },
            } },
            { 'Make your way to the Etched Rock at (K-9) for a cutscene.', sub = {
                { 'Follow the path — the Etched Rock is at the far end with no shortcut (except Cumulus Masque +1, which places you right by Ethereal Ingress #6).' },
                { 'From this point on you can pick up Ethereal Ingress points; they do not blink before being acquired. Most are on or close to the path; #3 and #4 in the northwest are the only substantial detour.' },
                { 'More than the first six exist: #7 is associated with Domain Invasion / Quetzalcoatl, #9 is south down the river from #5 with ???s useful for Geas Fete; others can\'t be unlocked yet.' },
            } },
        },
    },
