    ['Rhapsodies of Vanadiel Mission 3-14'] = {
        title        = 'Unshakable Nightmares',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Part of Selh\'teus\'s crystal must be cracked for you to become a god of light. What\'s more, you must also purge yourself of the ambassador\'s taint. Head to the Walk of Echoes to accomplish the latter task.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Enter the Walk of Echoes for a cutscene.', sub = {
                { 'All three entry methods below lead to the same section; the first is most easily accessible.' },
                { 'The blue ??? next to the Cavernous Maw & Survival Guide in Batallia Downs leads to the wrong Walk of Echoes — exit and use a different location (as of 5/12/2026, may simply work after leaving and returning).' },
                { 'If you receive a message about Champion of the Dawn, zone into Walk of Echoes from Xarcabard (S) to trigger that cutscene, then complete Champion of the Dawn and A Forbidden Reunion first. After completion, you can simply proceed to the next Mission.' },
                { 'Skip trick: enter via Xarcabard (S), get the block message, leave to Witchfire Glen, re-enter for the Champion of the Dawn cutscene, leave to Witchfire Glen again, and re-enter once more.' },
            } },
            { '── Entering the Walk of Echoes ──' },
            { 'Blue ??? next to the Cavernous Maws in Batallia Downs, Rolanberry Fields, or Sauromugue Champaign — past or present works; present-day Survival Guides are quickest.', sub = {
                { 'Requires Key Item Lightsworm from Wings of the Goddess Mission 2 (Back to the Beginning) or the early RoV Mission line; works if Back to the Beginning was completed after August 2015.' },
            } },
            { 'Verdical Conflux in Grauberg (S) at (F-5) — requires Wings of the Goddess Mission 46: When Wills Collide.' },
            { 'Verdical Conflux in Pashhow Marshlands (S) at (J-9) — requires Voidwatch Quest 15: Glimmer of Hope.' },
        },
    },
