        notes        = {

            { 'You cannot receive this cutscene if you are currently on one of these missions:', sub = {
                { 'Promathia Mission 8-1: Garden of Antiquity' },
                { 'Promathia Mission 8-4: Dawn (prior to final cutscenes)' },
                { 'Possibly other Tenzen-related missions' },
            } },
        },
    },
    ['Rhapsodies of Vanadiel Mission 3-22'] = {
        title        = 'From West to East',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Three of your allies have assembled on Reisenjima to help you see things to their conclusion: Gilgamesh, Aldo, and Tenzen. Work with them to vanquish eleven of the panopts befouling the natural order.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Defeat 11 Obstreperous Panopts.', sub = {
                { 'Many spawn around (F-11), just north of Ethereal Ingress #1.' },
                { 'Not difficult individually, but the area has many aggressive mobs.' },
                { 'Buy a Key Item Mollifier from Shiftrix beforehand — otherwise the NM Ascended Panopt can spawn.' },
                { 'Zoning resets progress; you receive a message after each kill showing how many remain.' },
                { 'Key Item Rhapsody in Fuschia reduces claimed Panopts to level 112 (from 122~124).' },
                { 'Record of Eminence — Combat (Region) > Combat (Escha 2) > Conflict: Reisenjima I covers killing ten of these.' },
            } },
        },
    },
    ['Rhapsodies of Vanadiel Mission 3-23'] = {
        title        = 'Good Things Come in Threes',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: You have succeeded in vanquishing the panopts. Head back to the entrance of the Sanctorium to meet up with your compatriots.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Examine the Etched Rock in Reisenjima at (K-9) for a cutscene.', sub = {
                { 'Ethereal Ingress #6, Sanctorium entrance.' },
            } },
        },
    },
    ['Rhapsodies of Vanadiel Mission 3-24'] = {
        title        = 'Tackling the Problem',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Your allies have also succeeded in culling their quarry. Return to the crystal and report your success to Selh\'teus and Iroha.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Examine the Reisen Crystal in Reisenjima Sanctorium for a cutscene.' },
        },
