    ['Rhapsodies of Vanadiel Mission 3-25'] = {
        title        = 'Way to Divinity',
        starting_npc = 'N/A',
        subtitle     = 'The Ascended',
        repeatable   = 'No',
        description  = 'Mission Orders: Your returning the lifestream to its pure state has enabled Selh\'teus to send you to Altana. What lies ahead is unclear--make sure you are prepared for the journey.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Watch the cutscene that started during the previous Mission — the next Mission begins when it ends.' },
            { 'You will be transported to the Empyreal Paradox during the cutscene.' },
        },
    },
    ['Rhapsodies of Vanadiel Mission 3-26'] = {
        title        = 'The Winds of Time',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: You have shed the last vestiges of your humanity to become a god of light. Altana has revealed the key: the fledgling deities of light and darkness must engage in heated combat to brew up the "winds of time." The Reckoning is at hand!',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Examine the Transcendental Radiance in Empyreal Paradox and enter the battlefield The Winds of Time.' },
            { 'Defeat Metus.', sub = {
                { 'Uses Promathia\'s TP moves: Bastion of Twilight, Wheel of Impregnability, Infernal Deliverance, Empty Salvation.' },
                { 'Also uses Osmotic Wave and Censure, and can cast Meteor.' },
                { 'Trust NPCs can be used for this battle.' },
            } },
            { 'After winning, a cutscene starts and the next Mission begins.' },
        },
        notes        = {

            { 'On failure, return to Reisenjima Sanctorium and click the Reisen Crystal, agree to meet the Goddess, and you return to Empyreal Paradox for a cutscene with Metus. Then enter the Transcendental Radiance room and use the Dimensional Portal to the right of the entrance to return to Reisenjima Sanctorium.' },
            { 'Click the Reisen Crystal again, agree to meet the Goddess, and receive Key Item Extradimensional scar required to attempt the fight again.', sub = {
                { 'This capability is lost once you\'re no longer on a RoV mission requiring access to Empyreal Paradox.' },
                { 'If you haven\'t reached Dawn in Chains of Promathia, you will be confined to the basement — no free trips to Al\'Taieu.' },
            } },
            { 'The Reisen Crystal in Reisenjima Sanctorium will also teleport you to Empyreal Paradox.' },
        },
    },
    ['Rhapsodies of Vanadiel Mission 3-27'] = {
        title        = 'Calm After the Storm',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Your heroic efforts successfully dispersed the Cloud of Darkness, and what you have shed to become a god of light has returned to you, meaning you are mortal once more. Return to Reisenjima, where your allies await.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Watch the cutscene that started after the previous fight.' },
            { 'If Tenzen is \'occupied\' in a Promathia Mission, you will be unable to continue until he is free.', sub = {
                { 'Example: you are on Dawn but have not completed the final cutscenes.' },
                { 'Examine the Resume Point in Empyreal Paradox to continue.' },
