    ['Rhapsodies of Vanadiel Mission 3-28'] = {
        title        = 'Nary a Cloud in Sight',
        starting_npc = 'N/A',
        subtitle     = 'The Savior of Vana\'diel',
        repeatable   = 'No',
        description  = 'Mission Orders: The winds of time have cleansed every corner of the land, and what was once bleak is now bright. However, this also means Iroha will soon disappear from the world. Spend a few final moments with her outside.',
