    ['Rhapsodies of Vanadiel Mission 3-29'] = {
        title        = 'An Unending Song',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Though Iroha may be gone, peace has come to Vana\'diel at last. Selh\'teus\'s crystal continues to shine, and soon the Emptiness will be no more. But your adventures will never end so long as you continue unceasingly forward.',
