quest_info['tvrmissions'] = {
    ['Epilogue Quests'] = {
        title        = 'Epilogue',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = '',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {},
    },
    ['The Voracious Resurgence Mission 1-1'] = {
        title        = 'The Voracious Resurgence',
        starting_npc = 'Gumbah, Bastok Mines (J-7)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'As long-lost truths begin to come to life, it falls to you to uncover the source of what eats at Vana\'diel from the inside.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Speak to Gumbah in Bastok Mines at (J-7), inside the back of the house on the upper walkway.', sub = {
                { 'Nearest HP #1.' },
            } },
        },
    },
    ['The Voracious Resurgence Mission 1-2'] = {
        title        = 'The Gloom Phantom\'s Approach',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'According to Cornelia, a Galkan Child was spotted wandering about in the Zeruhn Mines in need of aid. Head to the Zeruhn Mines.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Zone into Zeruhn Mines from Bastok Mines for a cutscene.', sub = {
                { '(Optional) Speak to Rasmus at (I-6) for some dialogue.' },
                { '(Optional) Speak to Makarim at (H-11) for some dialogue.' },
            } },
            { 'Touch the Disturbed Dirt at (K-9) for a cutscene.' },
            { 'Touch the Disturbed Dirt again to spawn Gloom Phantom.', sub = {
                { '15 minute time limit.' },
                { 'NM has approximately 30k HP and uses Blood Weapon and Brazen Rush.' },
            } },
            { 'After defeating Gloom Phantom, touch the Disturbed Dirt for another cutscene.', sub = {
                { 'If you zone before this cutscene, simply check the dirt again.' },
            } },
        },
    },
    ['The Voracious Resurgence Mission 1-3'] = {
        title        = 'The Brygid Cup',
        starting_npc = 'Gumbah, Bastok Mines (J-7)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Raebrimm seems to be threatened by the black-clad Goblin. The plan to protect him: find the perfect disguise. Perhaps the stylist extraordinare, Brygid, can help you over in Bastok Markets.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Speak to Gumbah in Bastok Mines HP #3 at (J-7).', sub = {
                { 'From HP #3, take the stairs mid-way on the right, go up, bust a left, cross the bridge on your right and make an immediate right, open the door. Gumbah is in the back room of the home, NOT next to the Home Point.' },
            } },
            { 'Speak to Brygid in Bastok Markets HP #4 (K-9) twice.' },
            { 'After agreeing to assist her, Brygid will direct you to pick one of several NPCs to cosplay for her fashion show.' },
            { '── NPC Outfits ──' },
            { 'Dress like your selected NPC exactly, ignoring weapons; focus on head/body/hands/legs/feet.' },
            { 'Azima — impossible to copy exactly (present-day clothing unobtainable); Shadowreign past style wins first prize.', sub = {
                { 'Past style: Witch Hat, Marduk\'s Jubbah, Marduk\'s Dastanas, Marduk\'s Shalwar, Sorcerer\'s Sabots.' },
                { 'A /lockstyle combo of Coven Hat, Marduk\'s Jubbah, Mdk. Dastanas +1, Mdk. Shalwar +1, Arch. Sabots +1 earned 20,202 Gil for first place (+2,000 Gil bonus over other entries).' },
            } },
            { 'Naji — Gavial Mail, Breeches, Battle Boots. No head or hand wear.' },
            { 'Black Mud — Wool Hat, Doublet, Slops, Ash Clogs. No hand wear.', sub = {
                { 'Easy option: Doublet and Slops from a Sparks vendor; Wool Hat from Chetak in Lower Jeuno (H-9).' },
            } },
            { 'Michea — Gambison, Brais, Gaiters. No head or hand wear.' },
            { 'Nbu Latteh — Bronze Harness, Scale Cuisses, Scale Greaves. No head or hand coverings.', sub = {
                { 'Easiest and cheapest: all 3 pieces ~3,000 from Brunhilde Armorer in Bastok Markets HP #1 (E-10), or very low Sparks cost.' },
            } },
            { 'Once dressed, head outside The Steaming Sheep in Port Bastok HP #3 (E-7) and speak to Ruenda while wearing your costume (turn /lockstyle off or use an Equip. Set).', sub = {
                { 'Long cutscene, 5+ minutes with fastCS and Enternity.' },
            } },
            { 'After the cutscene, speak to Brygid once more to receive your reward.' },
        },
        notes        = {

            { 'If running multiple accounts, any tradeable gear can be passed along to alts:', sub = {
                { 'Set and enable the lockstyle outside The Steaming Sheep (does not persist through zone), trade the gear to the next character, repeat.' },
            } },
        },
    },
    ['The Voracious Resurgence Mission 1-4'] = {
        title        = 'The Destiny Destroyers',
        starting_npc = 'Gumbah, Bastok Mines (J-7)',
        subtitle     = 'Destiny Destroyer...Destroyer',
        repeatable   = 'No',
        description  = 'The black-clad Goblin seems to have given up on Raebrimm, but now\'s no time to rest on your laurels. The Mythril Musketeers are hot on the trail; head to Korroloka Tunnel to assist them.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Speak to Gumbah in Bastok Mines HP #1 (J-7) for a cutscene.' },
            { 'Head to Korroloka Tunnel via Zeruhn Mines from Bastok Mines, or use the Survival Guide warp to Zeruhn Mines.' },
            { 'Interact with the Stalagmite targetable location in Korroloka Tunnel at (D-9) on Map 1 for a cutscene.', sub = {
                { 'This is the first map you arrive at when entering via the above methods.' },
                { 'The Stalagmite is on the bottom level. No need to follow the upper path.' },
            } },
            { 'Interact with the Stalagmite again to begin a fight against Gloom Phantom (WAR/DRK), Magh Bihu (RDM), and Dazbog (PLD).', sub = {
                { '15 minute time limit.' },
                { 'Each NM has approximately 30k HP and uses its respective job(s)\' SP Abilities.' },
                { 'Trio can coordinate skillchains and magic bursts on the same target (e.g. Gloom Phantom Rush -> Drill Claw (Fusion) -> Fire IV burst; Rush -> Thrashing Assault / Meeble Warble (Distortion) -> Water IV burst).' },
                { 'AA TT Trust can sleep the meeble and mandragora.' },
            } },
            { 'Interact with the Stalagmite after the fight for another cutscene.' },
            { 'Return to Gumbah for a cutscene and your reward.' },
        },
    },
    ['The Voracious Resurgence Mission 10-1'] = {
        title        = 'To Movalpolos!',
        starting_npc = 'Gumbah, Bastok Mines (J-7)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: According to Gumbah, a Galka has been sighted in a place known as Movalpolos. You have been asked to inform him that the gate has already been sealed. To Movalpolos!',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Speak to Gumbah in Bastok Mines HP #3 at (J-7), inside a house on the upper walkway in the back room, for a cutscene.' },
            { 'Travel to Oldton Movalpolos and speak to Tarnotik at (K-10) for a cutscene.', sub = {
                { 'Proto-Waypoint warp takes you to (K-10), closest.' },
                { 'Or Survival Guide to Movalpolos.' },
                { 'Or Escape in Newton Movalpolos and zone into Oldton Movalpolos, then run east to (K-10).' },
            } },
            { 'Unlock the Proto-Waypoint if needed by traveling through Newton Movalpolos.' },
            { 'In Oldton Movalpolos, travel to (E-13), talk to Twinkbrix, and trade 2,716 Gil for teleportation to Mine Shaft #2716.' },
            { 'Exit into Newton Movalpolos and travel to the furnace at (K-8).', sub = {
                { 'If the fence/gate blocks you heading south, trade a Firesand to the furnace to move it. Farm Firesand from Moblin Roadman/Engineer/Headman.' },
            } },
            { 'Drop off at (I/J-9) and continue running south to (E-9) (exit 4 on the map), then exit back into Oldton Movalpolos.', sub = {
                { 'The Geomagnetic Fount is on the left near the opening of the tunnel.' },
                { 'Alternative: Home Point to Newton Movalpolos and walk through the revolving gate (may need a Firesand), then south to exit 4 by dropping at (J-9).' },
            } },
            { 'Travel to Mine Shaft #2716 and interact with the Shaft Entrance for a cutscene.', sub = {
                { 'Tarnotik warps you to Mine Shaft #2716 for a Snow Lily.' },
                { 'Home Point warp to Newton Movalpolos is closest.' },
                { 'Twinkbrix in Oldton Movalpolos will warp you directly for 10k Gil (use the Oldton Movalpolos Survival Guide).' },
            } },
            { 'After the cutscene, interact with the BCNM entrance again and select "To Movalpolos!" to enter the battlefield.' },
            { 'Defeat Gloom Phantom, Awoken Vampyr Jarl, Awoken Ariri Samariri (has access to Death), and Awoken Hildesvini.', sub = {
                { 'Trusts allowed.' },
                { 'Jabbos assists and can tank one mob while you work on the rest; he engages when you draw your weapon regardless of distance.' },
            } },
            { 'After the fight, automatically enter a cutscene and receive your reward.' },
        },
    },
    ['The Voracious Resurgence Mission 10-2'] = {
        title        = 'Magh Bihu on the Prowl',
        starting_npc = 'Mandragora Warden, The Boyahda Tree Map 1 (F-4)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: You are destined for the Boyahda Tree in order to meet up with Jabbos once more. Magh Bihu is already en route. A friendly mandragora may be able to guide you to Magh Bihu\'s location if you give them a certain something.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Before heading out, get an Acidic Humus and a Watermelon for each party member.', sub = {
                { 'Acidic Humus: farm in Abyssea - Tahrongi. Warp to conflux #2, walk north, fight Pachypodiums for Alkaline Humus, trade Alkaline Humus to the ??? on the eastern side of (H-8) to spawn Gancanagh, which drops Acidic Humus. Or buy from AH (Others -> Misc. 2).' },
                { 'Watermelon: buy from Scamplix near HP #2 in Rabao (F-7).' },
            } },
            { 'Talk to the Mandragora Warden in The Boyahda Tree Map 1 at (F-4) and ask about Magh Bihu.', sub = {
                { 'There are two spots at (F-4); the correct one has its entrance from E-4 and only has a single Mandragora Warden.' },
                { 'Proto-Waypoint is nearby. Fastest: Home Point near the Cloister, walk towards exit F to the north. Unity Warp 135 to The Boyahda Tree is also close.' },
            } },
            { 'Trade an Acidic Humus to the Mandragora Warden for a cutscene.' },
            { 'Speak to the Mandragora Warden again and select "Where did Magh Bihu go?".' },
            { 'Trade a Watermelon for the final cutscene and your reward.' },
        },
    },
    ['The Voracious Resurgence Mission 10-3'] = {
        title        = '101 Dazbogs',
        starting_npc = 'Hedrov, Gusgen Mines (H-7)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: When you went with Magh Bihu to see Dazbog, you were asked to bring a suitable tribute to the lord. Bring the lord six hunks of fat worm meat.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Before heading out, farm Boulder Eaters in Gustav Tunnel at (J-6) Map 2 for 6 Fat Worm Meat (needed for Dazbog).', sub = {
                { 'Unity Warp 128 puts you on the correct map.' },
                { 'Drop rate is unreliable; Treasure Hunter helps. Items are Exclusive, so they cannot be purchased.' },
            } },
            { 'Head to Map 4 of Gusgen Mines (same map as Juggler Hecatomb) and speak with Hedrov at (H-7) for a cutscene.', sub = {
                { 'Fastest: Survival Guide, walk towards exit A. On the next map keep left and go down the tunnel at G to reach Map 4.' },
                { 'Alternative: through Tunnel B, then Tunnel E, west to Drop H on Map 3; drop down and you are next to Hedrov.' },
                { 'Hedrov is in the middle of the room behind a shed.' },
            } },
            { 'Trade the 6 Fat Worm Meat to Hedrov for a cutscene and reward.' },
        },
    },
    ['The Voracious Resurgence Mission 10-4'] = {
        title        = 'Kipdrix the Faithful',
        starting_npc = 'Tarnotik, Oldton Movalpolos (K-10)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: According to your allies, Magh Bihu and Dazbog have already arrived in Movalpolos. They are certainly seem to want you to meet the Gloom Phantom. Head to Mine Shaft #2716.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Speak to Tarnotik in Oldton Movalpolos at (K-10) for a cutscene to begin the mission.', sub = {
                { 'Proto-Waypoint warp takes you to (K-10), closest. Or Survival Guide to Movalpolos.' },
                { 'If you do not have the Proto-Waypoint, see The Voracious Resurgence Mission 10-1 for routing.' },
            } },
            { 'Enter Mine Shaft #2716 for a cutscene.', sub = {
                { 'Tarnotik warps you directly for a Snow Lily.' },
                { 'Home Point warp to Newton Movalpolos is closest.' },
                { 'Twinkbrix in Oldton Movalpolos will warp you directly for 10k Gil.' },
            } },
            { 'Return to Tarnotik for another cutscene.' },
            { 'Head to the Throne Room and interact with the Throne Room door for a cutscene.', sub = {
                { 'Home Point warp to Castle Zvahl Keep is closest.' },
            } },
            { 'Click the door again to enter the BCNM "Kipdrix the Faithful" with Orcish Warchief (PLD), Yagudo Inquisitor (SAM), and Topaz Quadav (WHM).', sub = {
                { 'They use their respective one-hour abilities.' },
                { 'All foes can be easily enfeebled, including Silence and Sleep.' },
                { 'Orcish Warchief applies a Blind aura, Yagudo Inquisitor an Addle aura, Topaz Quadav a Slow aura; auras are removed when that Beastman dies.' },
                { 'You are assisted by Magh Bihu and Dazbog, who engage when you draw your weapon.' },
            } },
            { 'After a cutscene you exit out into Xarcabard and receive your reward.' },
        },
    },
    ['The Voracious Resurgence Mission 10-5'] = {
        title        = 'Duke Alloces\'s Decision',
        starting_npc = 'Heroes\' Gambit, Xarcabard (J-9)',
        subtitle     = 'Another Psyche',
        repeatable   = 'No',
        description  = 'Mission Orders: The Demons, too, seem to have a traitor in their midst. Odin has permitted you to wield a Prime Weapon and has bid you defeat Chaos and Garazu Horeizu. Prepare for the battle and head to the throne room in Castle Zvahl.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Equip your upgraded Prime Weapon and interact with the Heroes\' Gambit targetable location at (J-9) in Xarcabard for a cutscene.', sub = {
                { 'Unity Warp 125 to Xarcabard is close.' },
                { 'Excludes Duban and Loughnashade.' },
            } },
            { 'Return to Castle Zvahl Keep and interact with the Valhallan Rift at (G-7) for a cutscene.', sub = {
                { 'Located directly across from the Home Point.' },
                { 'The Rift is not visible until you reach this point in the story.' },
            } },
            { 'Interact with the Valhallan Rift again to enter the BCNM "Duke Alloces\'s Decision" against Chaos (RDM/DRK).', sub = {
                { '15 minute time limit.' },
                { 'You are assisted by the Destiny Destroyers. They deal little damage but are very defensively strong; keep Reraise active so they can tank Chaos while you recover. If any Destiny Destroyer dies, the fight ends.' },
                { 'Chaos frequently casts a potent dispel that erases everything including stances and strips gear pieces.' },
                { 'Chaos is difficult to enfeeble (not immune). Manafont removes all enfeebles.' },
                { 'Any weapon can damage Chaos, not just Prime Weapons.' },
                { 'After triggering the pre-fight cutscene you may change to any job regardless of Prime Weapon possession.' },
            } },
            { 'After the cutscene you are moved to Xarcabard.' },
            { 'Return to the Heroes\' Gambit at (J-9) in Xarcabard for another cutscene; receive your gil reward and lose Key Item Despairing psyche.' },
        },
    },
    ['The Voracious Resurgence Mission 10-6'] = {
        title        = 'Odin\'s Eye',
        starting_npc = 'Heroes\' Gambit, Xarcabard (J-9)',
        subtitle     = 'Sender of Shadow',
        repeatable   = 'No',
        description  = 'Mission Orders: You finally meet up with Raebrimm. His soul has been severed in twain, and he appears to be suffering from partial memory loss. Collect the four pieces of his soul and head deeper in.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Change areas after completing the previous mission to begin this one.', sub = {
                { 'Twinkling Presence shards will not be visible if you are still on the previous mission.' },
            } },
            { 'Interact with the Heroes\' Gambit at (J-9) in Xarcabard for a cutscene to begin the mission.', sub = {
                { 'You will once again obtain Key Item Despairing psyche.' },
            } },
            { 'Enter Dynamis - Xarcabard and collect four other shards scattered around the zone.', sub = {
                { 'They appear as glowing targetable locations named Twinkling Presence; each grants a psyche key item (Suffering, Anguished, Rancorous, Determined).' },
                { 'Locations: NW section of (I-9) in the flat area surrounded by demons.' },
                { 'Locations: East side of (H-7) on top of the right cliff visible while walking up the ramp.' },
                { 'Locations: North middle of (F-7), above the Uleguerand Range zone in Xarcabard.' },
                { 'Locations: NW corner of (G-10).' },
            } },
            { 'You are transported out of Dynamis - Xarcabard when you begin the next cutscene.' },
            { 'Once all shards are collected, click the glowing Before Castle Zvahl at (D-7) (Dynamis Lord fight area) for a cutscene.', sub = {
                { 'Receive Key Item Raebrimm\'s memento.' },
            } },
            { 'Head back to Bastok Mines and talk to Gumbah at (J-7) for a cutscene and your reward.' },
        },
        notes        = {

            { 'You can now unlock two new Records of Eminence objectives. See Elijah in Upper Jeuno near Home Point #1.' },
        },
    },
    ['The Voracious Resurgence Mission 11-1'] = {
        title        = 'Moglesse Oblige',
        starting_npc = 'Moogle, Home Nation Mog House',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Your local Mog House moogle says that the time has come for moogle and adventurer to work as one. You must head to the stone circle in La Theine Plateau. Get a move on!',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Speak to your Moogle in the Mog House of your home nation for a cutscene.' },
            { 'Head to the Stone Circle in La Theine Plateau at (G-6) and interact with the ??? for a cutscene.', sub = {
                { 'UNM 99 warp to La Theine Plateau is the quickest route.' },
            } },
            { 'Interact with the Moogle Meeting targetable location in La Theine Plateau at (H-10) for a cutscene.', sub = {
                { 'You must exit from Map 3 in Ordelle\'s Caves to reach this location, near Morbolger.' },
                { 'Or use the Proto-Waypoint teleport to La Theine Plateau if unlocked; a party member with the Proto-Waypoint can warp others via Nexus Cape.' },
                { 'Cave route: from Ordelle\'s Caves entrance follow path B, then path D from Map 1; on Map 2 drop down the southeast hole at (H-11) to reach Map 3 and the 3rd exit to La Theine Plateau.' },
            } },
            { 'Interact with the Moogle Meeting again to enter the BCNM "Moglesse Oblige" against Spikehelm Argok (DRK Orc), Tethys (Gigas MNK), Garmatur the Merciless (Troll RDM), and Antican Curule Aedillis (BLM).', sub = {
                { 'Trusts allowed. All foes can be slept and silenced.' },
            } },
            { 'After winning, automatically enter a cutscene and receive your reward.' },
        },
    },
    ['The Voracious Resurgence Mission 11-2'] = {
        title        = 'The Voracious Beast',
        starting_npc = 'N/A',
        subtitle     = 'Astral Aligner',
        repeatable   = 'No',
        description  = 'Mission Orders: The time is nigh to vanquish the betrayer in Castle Zvahl and break the seal. Work with the beastmen and the Destiny Destroyers and claim victory.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Interact with the Heroes\' Gambit at (J-9) in Xarcabard for a cutscene to begin the mission.' },
            { 'Head to Castle Zvahl Keep / Throne Room Home Point and interact with the Valhallan Rift at (G-7) for a cutscene.' },
            { 'Interact with the Valhallan Rift again to enter the BCNM "The Voracious Beast" against Garazu-Horeizu (BLM/RDM).', sub = {
                { 'He uses all staff weaponskills, Chainspell paired with -ga IV nukes, and summons clones of you and the Destiny Destroyers. Only Garazu-Horeizu needs to die.' },
                { 'Buffs do not remain after entering the BCNM. Trusts allowed.' },
                { 'You are assisted by the Destiny Destroyers; they engage and approach when a party member engages.' },
            } },
            { 'After the cutscene, equip your stage 2+ Prime Weapon and interact with the Valhallan Rift again to enter "The Voracious Beast" against Chaos.', sub = {
                { 'Any weapon can damage Chaos, but all non-Prime weapons (and stage 1 Primes) deal -70% damage and cannot finish him off; the final hit must come from a Prime Weapon.' },
                { 'Everyone in the party must have their weapon equipped to queue and enter (does not apply to Duban / Loughnashade or to a cleared helper).' },
                { 'Trusts allowed and may be resummoned as needed.' },
                { 'You are assisted by Gurebu-Ougrebu and Medada.' },
                { 'Chaos regens if not taking damage and can self-Cure IV for over 30k. After his HP is taken low the first time, HP becomes invisible and Gurebu-Ougrebu and Medada are defeated, spawning the first two Profane Circle fetters; Chaos takes severely reduced damage while fetters are alive.' },
                { 'You are then assisted by Cornelia (Mythril Musketeer), Lehko Habhoka, Ragelise, Fickblix, and Luzaf, spawning one at a time; if defeated they become additional fetters.' },
                { 'Chaos\'s Black Sanctus applies a special doom counter; a living NPC sacrifices itself to take the hit. With no NPC present, it places a 30-minute curse timer with 5 Black Sanctus uses before killing the player. The move may fire as soon as an NPC spawns; it appears scripted so you cannot be afflicted until all NPCs are exhausted.' },
            } },
            { 'Receive Key Item Vial of Chaos\'s blood after the fight.' },
            { 'Return to the Heroes\' Gambit at (J-9) in Xarcabard for the final cutscene.', sub = {
                { 'You may defer picking a ring and return later, but the next mission will be started.' },
                { 'To reconsider your ring choice, drop the current reward ring and re-examine the Heroes\' Gambit one Conquest tally later for a new one at zero cost; if you toss the ring in Xarcabard, zone and re-enter before the Heroes\' Gambit allows a new selection.' },
            } },
        },
    },
    ['The Voracious Resurgence Mission 11-3'] = {
        title        = 'Your Decision',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: The threat to Valhalla and Vana\'diel has finally been vanquished, and beastmen and the enlightened races alike can walk hand in hand to secure a brighter future for all. Your choice has brought new light to the land.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Speak with Gama-Shama in the Silver Knife to learn about fully upgrading Prime Weapons.', sub = {
                { 'Your Gallimaufry cap is increased to 100,000,000.' },
            } },
            { 'Speak to Elijah to begin collecting Voracious Psyches.', sub = {
                { 'You must speak to him, zone, then speak again after completing The Voracious Resurgence to start collecting Psyches.' },
            } },
        },
    },
    ['The Voracious Resurgence Mission 2-1'] = {
        title        = 'Kupipi\'s Dilemma',
        starting_npc = 'Kupipi, Heavens Tower',
        subtitle     = 'Fully-Baked Hero',
        repeatable   = 'No',
        description  = 'Mission Orders: A conflict between Shantotto and Kupipi is coming to a head. Shantotto asked Kupipi to fix an old outfit, but Kupipi doesn\'t recall such a request. Ask Sassa-Kotassa, Sheelala, and Habida-Jubida in Heavens Tower to find out who is right.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Speak to Kupipi in Heavens Tower for a cutscene.' },
            { 'Trade the requested items to the 3 Tarutaru outside her office in the lobby of Heavens Tower.', sub = {
                { 'Sassa-Kotassa — Red Grass Cloth (AH: Materials > Clothcraft).' },
                { 'Sheelala — Yagudo Drink (Curio Vendor Moogle or AH: Food > Meals > Drinks).' },
                { 'Habida-Jubida — Dream Flower Petal (AH: Materials > Alchemy 1); drops from Alraune in Bibiki Bay - Purgonorgo Isle after it uses Dream Flower. Drop HP to 20% and spam Dia to speed it up.' },
            } },
            { 'Return to Kupipi for a cutscene; she asks for a White Rolanberry (Ripe White Rolanberry also works).' },
            { '── Obtaining the Rolanberries ──' },
            { 'AH route — buy White, Ripe White, or Rolanberry 854 from AH: Food > Ingredients.', sub = {
                { 'Not recommended to buy base Rolanberries from AH if doing the Crawler NM climb.' },
                { 'All types of Rolanberry stack to 12.' },
            } },
            { 'Crawler NM route — climb the force-pop Crawler NM chain in Crawler\'s Nest using the appropriate pop items.', sub = {
                { 'Fastest route: Crawler\'s Nest Survival Guide warp, then exit to Rolanberry Fields.' },
            } },
            { 'Trade a Rolanberry 854 to Pellio for either a White Rolanberry or Ripe White Rolanberry (50:50 chance).' },
            { 'Return to Kupipi and trade the White Rolanberry or Ripe White Rolanberry for a cutscene.', sub = {
                { 'Dialogue varies by HQ/NQ; the Ripe White version can be replayed via Mashua under Additional Stories (Kupipi\'s Dilemma pt.3).' },
            } },
            { 'Speak to Shantotto in Windurst Walls (K-7) for the final cutscene and 20,000 gil reward.', sub = {
                { 'Title may not auto-grant; verify via Burute-Sorute in Windurst Walls (H-10) under the 400 gil option.' },
            } },
        },
    },
    ['The Voracious Resurgence Mission 2-2'] = {
        title        = 'The Cardian\'s Duty',
        starting_npc = 'Shantotto, Windurst Walls (K-7)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Shantotto is lamenting that many seem to have memory issues of late. She thinks a sinister force is behind this. Aid Kupipi in getting to the bottom of it.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Speak to Shantotto in her manor at Windurst Walls (K-7) for a cutscene (no zoning required from previous mission).' },
            { 'Speak to Kupipi in Heavens Tower for a cutscene.', sub = {
                { 'Optional: speak to Sassa-Kotassa, Sheelala, and Habida-Jubida in the lobby for hints to your next destination.' },
            } },
            { 'Head to East Sarutabaruta (J-8) and examine the Disturbed Earth for a cutscene (south of the Tower, close to canyon wall).', sub = {
                { 'Fastest route: Unity Warp (Level 99) to East Sarutabaruta or Survival Guide to Inner Horutoto Ruins.' },
            } },
            { 'Examine the Disturbed Earth again to spawn a battle (15-minute limit) against Yagudo Vicar (WHM), Yagudo Centurion (BLM), and two Yagudo Underlings (NIN, MNK).', sub = {
                { 'Each NM has approx 30k HP and access to its job\'s SP ability.' },
                { 'King of Spades (PLD) assists and uses Invincible at low HP — you lose if he dies. NMs initially focus him.' },
                { 'AA TT Trust Sleepga works on the NMs.' },
            } },
            { 'Examine the Disturbed Earth once more after the battle for a cutscene.' },
            { 'Return to Heavens Tower and speak with Kupipi for the final cutscene and your reward.' },
        },
    },
    ['The Voracious Resurgence Mission 2-3'] = {
        title        = 'Zhuu Buxu\'s Gambit',
        starting_npc = 'Kupipi, Heavens Tower',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: You have to retrieve the doll stolen from Heavens Tower with all due haste. A simple adventurer would attract little suspicion from the Yagudo. Your first task is to deliver a star-crested summons to Tosuka-Porika in the Optistery and receive further instructions.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Speak to Kupipi in Heavens Tower for a cutscene to receive Key Item Star-crested summons (zoning not required after previous mission).' },
            { 'Speak to Tosuka-Porika in Windurst Waters HP #1 in the Optistery (G-8) Map 1 for another cutscene.' },
            { 'Examine the Worn Chest in the storage room of the Giddeus basement at (F-6) Map 2.', sub = {
                { 'Drop via E on the map; click the door (not the Yagudo guard) to enter the treasure room.' },
                { 'No preemptive cutscene — you are immediately attacked by a Yagudo Lookout (SAM, approx 30k HP, 15-minute limit). Uses Meikyo Shisui near 66% HP and Yaegasumi near 33% HP.' },
            } },
            { 'Examine the Worn Chest again after the battle for a cutscene and Key Item Strange doll.', sub = {
                { 'If you zone before checking it again, you can return and re-check without fighting again.' },
            } },
            { 'Return to Tosuka-Porika in Windurst Waters for a cutscene and your reward.' },
        },
    },
    ['The Voracious Resurgence Mission 2-4'] = {
        title        = 'Star Onion Fortune',
        starting_npc = 'Tosuka-Porika, Windurst Waters (G-8) Map 1',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: The doll you retrieved from Giddeus is no more than a child\'s plaything. Return it to its owner near a warehouse near the waterfront in Windurst.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Speak to Tosuka-Porika again for a cutscene (no zoning needed).' },
            { 'Speak to Kohlo-Lakolo in Port Windurst (G-5) HP #1 behind Warehouse 1 for a cutscene.', sub = {
                { 'Optional: speak to him again for a hint, or to Shanruru for an additional cutscene.' },
            } },
            { 'Open your Temporary Key Item menu and examine Piece of evidence to see a cipher.' },
            { 'Speak to Kohlo-Lakolo again; when asked if you deciphered the evidence, say yes.', sub = {
                { 'The encrypted message is a simple Caesar cipher reading: "I require the special egg and a very strong individual. First comes the egg."' },
            } },
            { 'Travel to The Boyahda Tree Map 1 (bottom floor) and check the Muggy Air at (D-5), (H-6), or (H-9).', sub = {
                { 'Unity Warp (Level 125) to The Boyahda Tree, then turn around to zone to Map 1.' },
                { 'Only one site is active per attempt; the active site has a white glowing animation — check all three if needed.' },
            } },
            { 'Touch the active Muggy Air to spawn the Templar Crawler NM.', sub = {
                { 'Deals enhanced damage via Poison Breath and appears to gain an additional Protect buff after using Cocoon.' },
                { 'Each party member receives Key Item Sublime lucky egg on defeat.' },
            } },
            { 'Return to Kohlo-Lakolo for a cutscene and your reward.' },
        },
    },
    ['The Voracious Resurgence Mission 2-5'] = {
        title        = 'The Doll Whisperer',
        starting_npc = 'Kohlo-Lakolo, Port Windurst (G-5)',
        subtitle     = 'Ghdwk Vshdnhu (Death Speaker)',
        repeatable   = 'No',
        description  = 'Mission Orders: Honoi-Gomoi is planning to parley with the Yagudo behind a magic tower in West Sarutabaruta. However, you have the egg that the Yagudo require. Disrupt their plans.',
        series       = 'The Voracious Resurgence',
        previous     = '',
        next         = '',
        walkthrough  = {

            { 'Speak to Kohlo-Lakolo for a cutscene (no zoning needed).', sub = {
                { 'Optional: speak to him again, the other S.O.B.s, or Nanaa Mihgo in Windurst Woods (J-3) for additional dialogue.' },
            } },
            { 'Examine the Secluded Spot in West Sarutabaruta (J-8) for a cutscene (south of the Tower, behind the tree; closest to Windurst Waters HP #1 - E).' },
            { 'Examine the Secluded Spot again to begin a confrontation with Chepelle (BST).', sub = {
                { 'Starts with Chepelle\'s Tiger; summons Chepelle\'s Sheep around 75% HP and Chepelle\'s Hare around 50% HP (pets are sleepable and need not be killed).' },
                { 'Uses Familiar at 60% HP and again every minute thereafter.' },
                { 'High damage resistance; favors Axe weapon skills with Detonation and Distortion skillchains.' },
