    ['Building Bridges'] = {
        title        = 'Building Bridges',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'Thanks to the enemy destroying a bridge along the path of their attack, the unit assaulting Periqia is at an impasse. Find and activate the backup bridge mechanism rumoured to be hidden in the area.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Corporal',
        time_limit   = '15 minutes',
        mission_orders = 'Activate the bridge',
        recommended_lv = 'Lvl. 70',
        walkthrough  = {

            { 'Activate the four switches in the west, south, north, and east rooms at (F-8), (H-10), (H-6), and (J-8).', sub = {
                { 'Start area is a small map blocked off from the rest; head north-east to reach the main map.' },
                { 'Switches can be activated in any order and remain activated permanently.' },
            } },
            { 'Examine the Rune of Release in the center room at (H-8).' },
        },
    },
    ['Counting Sheep'] = {
        title        = 'Counting Sheep',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'The Imperial Army on the eastern front is being hit by a peculiar cold wave, and warm uniforms are in short supply. Buy as many sheep as you can from the markets in Leujaoam and save the troops.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Corporal',
        time_limit   = '15 minutes',
        mission_orders = 'Buy black sheep',
        recommended_lv = 'Lvl. 60',
        walkthrough  = {

            { 'Free as many Karakuls trapped behind ice walls as possible by completing tasks for the 4 Qiqirn NPCs at the entrance.' },
            { '── Qiqirn Mine Baron ──' },
            { 'Mine ores with the Pickaxe temp item, then talk to him again to trade them for Imperial Currency.', sub = {
                { 'Copper Ore > Imperial Bronze Piece.' },
                { 'Silver Ore > Imperial Silver Piece.' },
                { 'Gold Ore > Imperial Gold Piece.' },
            } },
            { '── Qiqirn Greengrocer ──' },
            { 'Harvest with the Sickle temp item, then trade harvests back for food temp items.', sub = {
                { 'Beaugreens > Pamamas.' },
                { 'Frost Turnip > Date.' },
                { 'Snow Lily > Pamama au Lait.' },
            } },
            { '── Qiqirn Dealer ──' },
            { 'Gamble for an Imperial Gold Piece by rolling as close to 1000 without going over; beat his total to win.', sub = {
                { 'Costs 5 Imperial Bronze Pieces or 1 Imperial Silver Piece to play.' },
                { 'The game is heavily tilted in the Dealer\'s favor and he cheats.' },
            } },
            { '── Qiqirn Shepherd ──' },
            { 'Pay 1 Imperial Gold Piece, 4 Imperial Silver Pieces, or 20 Imperial Bronze Pieces; escort the shepherd to an ice wall to blow it up with Qiqirn Mines.', sub = {
                { 'Shepherds sometimes stop to ask for harvested food before continuing; any party member may feed them.' },
                { 'Two of the five blocked rooms contain another Shepherd (who runs back to the start) and a Karakul.' },
                { 'You must click the Karakul inside the room after the wall is destroyed for it to count.' },
            } },
        },
    },
    ['Searat Salvation'] = {
        title        = 'Searat Salvation',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'Qiqirn divers assigned the duty of demolishing wrecks on the Ilrusi Atoll have run into a problem with the local wildlife. Lead them back to safety before they decide to abandon their work.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Corporal',
        time_limit   = '15 minutes',
        mission_orders = 'Save the Qiqirn Divers',
        recommended_lv = 'Lvl. 60',
        walkthrough  = {

            { 'Guide one or more NPC Qiqirn Divers from (F-10) to the Qiqirn Chief Diver at (J-6).', sub = {
                { 'Talk to a Qiqirn Diver to make it follow you; one player can lead multiple Divers.' },
                { 'Giant Orobons patrol the map and will chase Qiqirns; if spotted, the Diver flees at enhanced speed.' },
                { 'If a Diver is scared off, click it again to resume following.' },
            } },
            { 'Bring at least one Diver to the Chief to spawn the Rune of Release.', sub = {
                { 'Maximum 1166 points for escorting all 5 Divers with 3 people.' },
                { '916 points for bringing 3 Divers with 3 or fewer participants.' },
            } },
        },
    },
    ['Siegemaster Assassination'] = {
        title        = 'Siegemaster Assassination',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'The Trolls have recruited Borgerlur, a siege specialist from central Aradjiah. The empire cannot allow him to take control of the Troll army. Find and eliminate Borgerlur as he travels through Lebros Cavern.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Corporal',
        time_limit   = '30 minutes',
        mission_orders = 'Assassinate Borgerlur',
        recommended_lv = 'Lvl. 70',
        walkthrough  = {

            { 'Eliminate Borgerlur, disguised as one of the Old Trolls.', sub = {
                { 'Trolls repop quickly (every 3 min 45 sec) and now auto-aggro; track originals vs respawns.' },
                { 'The Borgerlur Troll never changes; once defeated, all others despawn and the assault ends.' },
                { 'Respawned mobs inherit hate on Borgerlur\'s current target if engaged.' },
            } },
            { 'Once Borgerlur is defeated, examine the Rune of Release at (G-7).' },
        },
    },
    ['The Double Agent'] = {
        title        = 'The Double Agent',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'There is a double agent among the Imperial Qiqirn spies in the Mamool Ja Training Grounds. Find him before he puts the other spies in danger.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Corporal',
        time_limit   = '30 minutes',
        mission_orders = 'Apprehend the spy',
        recommended_lv = 'Lvl. 70',
        walkthrough  = {

            { 'Find and capture the Qiqirn spy using hints from the other Qiqirn Spy NPCs scattered across the map.', sub = {
                { 'Aggressive Puks roam the map; sleep, charm, or distract them.' },
                { 'Talking to a Qiqirn gives 3 options: Capture, Talk, Nothing.' },
                { 'All Qiqirn tell the truth except the spy.' },
            } },
            { '── Direction hints ──' },
            { 'Should be close — spy is nearby.' },
            { 'Should be far — spy is distant.' },
            { '<X> amount of Yalms away — exact distance.' },
            { 'Some Qiqirns are clueless and give no info.' },
            { '── Strategy ──' },
            { 'Talk to multiple Qiqirn in an area; the one whose direction conflicts with the others is the spy.' },
            { 'When the spy is found he says "... how you know that?".' },
            { 'Falsely accusing a Qiqirn locks you out of further info from it and costs Assault Points.' },
            { 'Quick-completion: just select Capture on every Qiqirn until you win.' },
            { 'Examine the Rune of Release in the southwest portion of (I-8); AP reward is 1200 base minus 66 per false accusation.' },
        },
    },
    ['Deserter'] = {
        title        = 'Deserter',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'Agents of our Anti-Corsair Task Force have gone AWOL and are hiding somewhere in Ilrusi. Your mission is to swiftly disarm the deviants and take them into custody. All information on these criminals is highly classified and any disclosure of their identity is strictly prohibited.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Chief Sergeant',
        time_limit   = '30 minutes',
        mission_orders = 'Locate the agents',
        recommended_lv = 'Lvl. 70',
        walkthrough  = {

            { 'Subdue at least one Lamia or Merrow by breaking its weapon.', sub = {
                { 'Weapons can break from critical-hit weaponskills and critical hits.' },
                { 'At iLvl, a Dual Wield job like RDM with Haste II/Temper II and two DMG1 daggers breaks weapons in about 10 seconds.' },
                { 'A disarmed Lamia/Merrow immediately surrenders and becomes an NPC.' },
            } },
            { 'There are 12 Lamia and Merrow; you may end the assault any time after the first subdual.', sub = {
                { 'Subduing more monsters gives a higher point reward.' },
                { 'Once all 12 are killed or subdued, the Rune of Release spawns automatically if at least one was subdued.' },
            } },
            { 'Examine the Rune of Release at the starting NPC.' },
        },
    },
    ['Egg Conservation'] = {
        title        = 'Egg Conservation',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'There have been reports that Qiqirn hunters have been collecting the eggs of our army\'s messenger apkallus. You are to join forces with the male apkallus in the area and eliminate the invading Qiqirn while protecting the females and their eggs.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Chief Sergeant',
        time_limit   = '30 minutes',
        mission_orders = 'Drive out the hunters',
        recommended_lv = 'Lvl. 70',
        walkthrough  = {

            { 'Destroy the Qiqirn while keeping the Apkallu healed; Apkallu are curable and buffable.', sub = {
                { 'Smaller (female) Apkallu do not aid you; if all are defeated, the assault fails.' },
                { 'Larger (male) Apkallu auto-attack nearby Qiqirn but stop helping if damaged beyond 50%.' },
                { 'Qiqirn approach in pairs or solo from east and west; stay near the apkallu gaggle.' },
                { 'Drag Qiqirn through the middle of the pack to get male Apkallu to engage.' },
            } },
            { 'Defeat 15 Qiqirn (they keep spawning until the count is met).' },
            { 'Examine the Rune of Release at (I-8) when all Qiqirn are defeated.' },
        },
    },
    ['Imperial Code'] = {
        title        = 'Imperial Code',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'The Empire\'s mercury cipher (OGMA) has been stolen by a group of far eastern spies. With it, our enemies will be able to decrypt top-secret military orders, thus severely compromising Imperial safety. You are to intercept the enemy as they transfer the device.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Chief Sergeant',
        time_limit   = '30 minutes',
        mission_orders = 'Retrieve the OGMA',
        recommended_lv = 'Lvl. 70',
        walkthrough  = {

            { 'Defeat the 3 NIN NMs Oko, Danzo, and Saizo; each leaves a ??? after fading. The last ??? is the OGMA, which spawns the Rune of Release when retrieved.', sub = {
                { 'Oko and Danzo dual wield katanas; Saizo uses a great katana and can Mijin Gakure.' },
                { 'Oko and Saizo each have a Kusa very nearby — pull first or sleep it.' },
            } },
            { 'Examine the Rune of Release on the border of (G-8) and (H-8) on the lower level, right under a drop-down from above.' },
            { '── Notes ──' },
            { 'The 3 NMs and Kusa are humanoid ninjas — self-buff utsusemi, cast ninjutsu, use katana/great-katana WS; true sight aggro.' },
            { 'All mobs in this assault appear to resist drain effects.' },
            { 'Kusa are susceptible to lullaby and other light-based sleeps.' },
            { 'Kudagitsunes are Bhoots — aggressive to sound and low HP — and immediately use Perdition on aggro within ~10\'.', sub = {
                { 'Perdition is an instant-death ability that can kill you regardless of level.' },
            } },
        },
    },
    ['Marids in the Mist'] = {
        title        = 'Marids in the Mist',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'Our agents have informed us that the Mamool Ja have been training marids to use during sieges on the Empire. You are to locate these deadly beasts and capture or eliminate them before it\'s too late.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Chief Sergeant',
        time_limit   = '30 minutes',
        mission_orders = 'Neutralize the Marids',
        recommended_lv = 'Lvl. 70',
        walkthrough  = {

            { 'Kill or subdue all 8 Marids; subduing gives more Assault Points.', sub = {
                { 'Subdue by using the Thunderguard Dart temp item; success despawns the marid as captured.' },
                { 'Best when the Marid has 0 TP (post-WS) and below 50% HP — capture is nearly guaranteed.' },
            } },
            { 'Obtain Thunderguard Darts from the starting NPC Zimahd; he has unlimited supply but each person can carry only one at a time.' },
            { 'Examine the Rune of Release at the southwest of (I-9) once all 8 marids are captured or killed.', sub = {
                { '1333 base points for capturing all 8 marids (2198 solo with assault band bonus).' },
                { '266 base points for killing all 8 marids.' },
            } },
        },
    },
    ['Operation: Snake Eyes'] = {
        title        = 'Operation: Snake Eyes',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'Generals Karazahm and Umarid of the Imperial Army\'s Arrapago division have disappeared from camp headquarters while on a mission on Sharug Isle. There is a high possibility that the two have been kidnapped by members of the Undead Swarm.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Chief Sergeant',
        time_limit   = '30 minutes',
        mission_orders = 'Locate the generals',
        recommended_lv = 'Lvl. 70',
        walkthrough  = {

            { 'Defeat the 5 Qutrub scattered around the start at (I-9) to unlock the doors to the north.' },
