    ['Azure Ailments'] = {
        title        = 'Azure Ailments',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'To protect against an outbreak of the dreaded kraken flu, data is required on the effects of the disease. Healthy volunteers are wanted to travel to the Mamool Ja Training Grounds and collect important supplies.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Second Lieutenant',
        time_limit   = '30 minutes',
        mission_orders = 'Gather pathological data',
        recommended_lv = 'Lvl. 70',
        walkthrough  = {

            { 'Collect 3 negative status effects, registering each with Soulflayer Garjham at (H-8).', sub = {
                { 'Talk to Garjham a second time after 3 effects are registered to unlock the Rune of Release.' },
            } },
            { '── Status Effects and Sources ──' },
            { 'Amnesia — Qiqirn Huckster, Kibosh.' },
            { 'Bio — Poroggo, spell.' },
            { 'Disease — Pit Lindwurm, Foul Breath.' },
            { 'Slow — Huge Spider Spider Web, or Pit Lindwurm Chomp Rush.' },
            { 'STR Down — Bugard, Awful Eye.' },
            { 'Attack Down — Leech, Acid Mist (AoE).' },
            { 'Evasion Down — Slavering Lizard, Infrasonics (conic).' },
            { '── Strategy Tips ──' },
            { 'Bring a charm-capable job — leeches, lizards, spiders, raptors can all be charmed; all effects except Bio and Amnesia can be caught in cone range when the pet is hit.' },
            { 'Spiders + Poroggos give 2 easy effects; raptors give Slow and Disease; leeches rarely use Acid Mist.' },
            { 'Significantly harder at level 99 — bring Regen/Protect plus BLM sub. Pull mobs to the NPC, -ga unequipped to drop them near 10%, then DMG:1 weapon naked until debuffed, then talk to the NPC.' },
            { 'Alternative: level cap 70 party (tank, healer, DPS) — DNC at 70 cap also viable but struggles vs Mamool Ja or links. Bring Reraise Earrings.' },
            { 'Another option: heal-capable subjob with a 1-damage weapon like Signet Staff — drop target to ~10%, tap until the debuff lands (resists are common).' },
            { 'Protip: PLD with Weathering Shield (or Bullwhip Belt for more job coverage) gives negative elemental resistance, helping debuffs land.' },
        },
    },
