quest_info['sandoria'] = {
    ['A Boy\'s Dream'] = {
        title             = 'A Boy\'s Dream',
        starting_npc      = 'Ailbeche, Northern San d\'Oria J-8',
        subtitle          = 'None',
        repeatable        = 'Yes',
        description       = 'All fishermen dream of hooking the big one. Catch him and obtain the treasure in his belly.',
        required_fame     = 'San d\'Oria Fame Level: Unknown',
        level_restriction = 'Level 50+ Paladin',
        pack              = 'None',
        requirements      = 'Giant Shell Bug Odontotyrannus Key Item Knight\'s boots',
        rewards           = 'Gallant Leggings',
        previous_quest    = 'Sharpening the Sword',
        next_quest        = 'Under Oath and Borghertz\'s Stalwart Hands',
        note              = 'Be careful to do the above NPC interactions, as if skipped you will use up the Giant Shell Bug you get during the next step. Fish with a rod used for catching big fish in Castle Oztroja using Giant Shell Bug as bait. Fishing skill is not required. You will want to bring more than one Giant Shell Bug. A Clothespole from the Fishing Guild Merchant or Composite Fishing Rod from the Auction House are likely the easiest to obtain. However, even a rod not designed for large fish, such as a Willow Fishing Rod may be successfully used. From the entrance, go through the Brass Door at (I-8) on Map 1. Be careful about the trapdoor, you can avoid falling down by quickly moving after triggering the lever if you select the wrong one. On Map 2, walk towards exit (F) at (G-7). On the next map, head to (I). You will then be on map 7. On map 7 head towards (H-8)/(H-9) (middle of the big square room in the middle of Map 7) and fish in the pond. There are 2 Oozes in the pond. Castle Oztroja Map 1 Castle Oztroja Map 2 Castle Oztroja Map 7 Odontotyrannus (Monster) will be fished up and drops Odontotyrannus. Note that the fish can be sent to other characters on the same account. Odontotyrannus (Monster) may be immediately fished up again after defeat if needing multiple Odontotyrannus for other players. You can fish up Odontotyrannus (Monster) before trading Ailbeche the Giant Shell Bug in the previous step. Return Ailbeche and trade them the Odontotyrannus. Head to Selbina and trade Trade Zaldon (H-9), (inside the Fisherman\'s Guild) the Odontotyrannus and receive the Key Item Knight\'s boots. Return to and speak with Ailbeche again. Speak with Exoroche at Helbort\'s Blades in Southern San d\'Oria (K-7) one last time. Finally, head to Chateau d\'Oraguille and select Trion\'s door (Prince Royal\'s Rm, H-7) to receive your Gallant Leggings. Retrieved from "https://www.bg-wiki.com/index.php?title=A_Boy%27s_Dream&oldid=754358" window[\'nitroAds\'].createAd(\'bgwiki-anchor\', { "refreshLimit": 0, "refreshTime": 30, "format": "anchor", "anchor": "bottom", "report": { "enabled": true, "icon": true, "wording": "Report Ad", "position": "top-right" },  "mediaQuery": "(min-width: 0px)" }); window[\'nitroAds\'].createAd(\'nitro-video\', { "refreshTime": 30, "format": "floating", "report": { "enabled": true, "icon": true, "wording": "Report Ad", "position": "top-left" } }); Categories: QuestsSan d\'Oria QuestsRepeatable QuestsNorthern San d\'Oria QuestsPaladin Artifact QuestsFFXI Wiki',
        walkthrough       = {
            { 'Speak with Ailbeche.' },
            { 'Talk to Exoroche at Helbort\'s Blades in Southern San d\'Oria (K-7).' },
            { 'Return to and speak with Ailbeche again.' },
            { 'Trade Ailbeche a Giant Shell Bug.', sub = {
                { 'Either buy one off the Auction House, or go to Crawler\'s Nest and defeat Dreadbug via the ??? on map 2, SW of H-9.' },
                { 'He can drop up to 4 Giant Shell Bug.' },
                { 'If you are planning to complete this quest for other characters on the same account in one trip, you may pop Dreadbug again, only while this quest is still active, on subsequent new game days, once per game day.' },
                { 'Note: Be careful to do the above NPC interactions, as if skipped you will use up the Giant Shell Bug you get during the next step.' },
            } },
            { 'Fish with a rod used for catching big fish in Castle Oztroja using Giant Shell Bug as bait. Fishing skill is not required.', sub = {
                { 'You will want to bring more than one Giant Shell Bug.' },
                { 'A Clothespole from the Fishing Guild Merchant or Composite Fishing Rod from the Auction House are likely the easiest to obtain.', sub = {
                    { 'However, even a rod not designed for large fish, such as a Willow Fishing Rod may be successfully used.' },
                } },
            } },
            { 'From the entrance, go through the Brass Door at (I-8) on Map 1. Be careful about the trapdoor, you can avoid falling down by quickly moving after triggering the lever if you select the wrong one.', sub = {
                { 'On Map 2, walk towards exit (F) at (G-7).' },
                { 'On the next map, head to (I). You will then be on map 7.' },
                { 'On map 7 head towards (H-8)/(H-9) (middle of the big square room in the middle of Map 7) and fish in the pond. There are 2 Oozes in the pond.' },
            } },
            { 'Odontotyrannus (Monster) will be fished up and drops Odontotyrannus. Note that the fish can be sent to other characters on the same account.', sub = {
                { 'Odontotyrannus (Monster) may be immediately fished up again after defeat if needing multiple Odontotyrannus for other players.' },
                { 'You can fish up Odontotyrannus (Monster) before trading Ailbeche the Giant Shell Bug in the previous step.' },
            } },
            { 'Return Ailbeche and trade them the Odontotyrannus.' },
            { 'Head to Selbina and trade Trade Zaldon (H-9), (inside the Fisherman\'s Guild) the Odontotyrannus and receive the Key Item Knight\'s boots.' },
            { 'Return to and speak with Ailbeche again.' },
            { 'Speak with Exoroche at Helbort\'s Blades in Southern San d\'Oria (K-7) one last time.' },
            { 'Finally, head to Chateau d\'Oraguille and select Trion\'s door (Prince Royal\'s Rm, H-7) to receive your Gallant Leggings.' },
        },
    },
