    ['Unlocking a Myth'] = {
        title             = 'Unlocking a Myth',
        starting_npc      = 'Zalsuhm, Lower Jeuno (H-9)',
        subtitle          = 'None',
        repeatable        = 'No',
        description       = 'Self-styled leading researcher of mystical artifacts, Zalsuhm, claims that the weapon you acquired deep within Nyzul Isle conceals immense power. Wielding the now unlocked weapon will cause a magical evolution to take place...eventually.',
        level_restriction = 'None',
        pack              = 'None',
        requirements      = 'Vigil Weapon equipped.',
        rewards           = 'The ability to use your job\'s Mythic Weapon Skill with any weapon of the same type.',
        previous_quest    = 'None',
        next_quest        = 'None',
        walkthrough       = {

            { 'Speak to Zalsuhm inside Muckvix\'s Junk Shop in Lower Jeuno (H-9) with a Vigil Weapon equipped for a cutscene.' },
            { 'With the same Vigil weapon equipped in the main hand, fight enemies that grant EXP (Incredibly Easy Prey or better) and perform Weapon Skills and Skillchains to accumulate 250 Weapon Skill Points.', sub = {
                { 'Weapon skills used before starting this quest do not count.' },
            } },
            { 'Once you have enough points, your new Weapon Skill appears under your list of Weapon Skills, but only with the Vigil Weapon equipped.' },
            { 'Return to Zalsuhm and trade him your Vigil Weapon.', sub = {
                { 'He unlocks the Weapon Skill for use with any weapon and returns the Vigil Weapon to you.' },
            } },
        },
        notes             = {

            { 'Trading your Vigil Weapon to Zalsuhm before unlock gives a rough progress gauge:', sub = {
                { '"I sense only a mote of energy present. You still have a long way to go."' },
                { '"I can feel a marked increase in energy compared to when I first held it. Keep up the good work."' },
                { '"The energy is threatening to burst forth. It won\'t be long now."' },
                { '"You\'ve done it! Energy is overflowing as though the floodgates have burst open!"' },
            } },
            { 'Storing a Vigil Weapon with Ghanraam at Aht Urhgan Whitegate (K-10) resets its Weapon Skill Points.' },
            { 'After this quest the Vigil Weapon can still be used for Mythic Weapon acquisition quests; the WS points are not needed again so it is okay to store it.' },
            { 'For the first 1.5 years (2007-2008) Vigil Weapons were only obtainable on Floor 100.' },
            { 'Prior to the July 2014 update, required WS Points were determined by floors cleared in Nyzul Isle Investigation.' },
            { 'Around the May 2025 update, WS point rewards were significantly increased — the quest is much faster now.' },
        },
    },
