        next_quest        = 'Scattered Into Shadow',
        note              = 'The following monsters drop the Delkfutt Chest Key: Gigas Wallwatcher Gigas Kettlemaster Evil Spirit Gigas Spirekeeper Gigas Torturer Gigas Bonecutter Gigas Stonemason Gigas Punisher Gigas Hallwatcher Gigas Sculptor Magic Urn Light Elemental Thunder Elemental Retrieved from "https://www.bg-wiki.com/index.php?title=Wings_of_Gold&oldid=730633" window[\'nitroAds\'].createAd(\'bgwiki-anchor\', { "refreshLimit": 0, "refreshTime": 30, "format": "anchor", "anchor": "bottom", "report": { "enabled": true, "icon": true, "wording": "Report Ad", "position": "top-right" },  "mediaQuery": "(min-width: 0px)" }); window[\'nitroAds\'].createAd(\'nitro-video\', { "refreshTime": 30, "format": "floating", "report": { "enabled": true, "icon": true, "wording": "Report Ad", "position": "top-left" } }); Categories: QuestsJeuno QuestsUpper Jeuno QuestsBeastmaster Artifact QuestsFFXI Wiki',
