    ['Yet Another Trial in Tandem'] = {
        title             = 'Yet Another Trial in Tandem',
        starting_npc      = 'Luto Mewrilah, Upper Jeuno (G-8)',
        subtitle          = 'None',
        repeatable        = 'No',
        description       = 'Your comrade\'s zeal for self- improvement knows no limits, and the Magian Mooglehood stands ever ready to assist in this endeavor. Make your way to Ru\'Lude Gardens, where a new challenge awaits!',
        required_fame     = 'Jeuno Fame Level: Unknown',
        level_restriction = 'None',
        pack              = 'None',
        requirements      = 'Job level 75+ Adventuring Fellow level 76+ Key Item Magian trial log',
        rewards           = 'Raises Adventuring Fellow level cap to 85',
        previous_quest    = 'A Trial in Tandem, Redux',
        next_quest        = 'A Quaternary Trial in Tandem',
        walkthrough       = {

            { 'Speak with Luto Mewrilah for a cutscene that begins the quest and provides Key Item Magian Mooglehood missive.' },
            { 'Speak to the Magian Moogle in Ru\'Lude Gardens at (H-5) for a cutscene and a Tandem Necklace +2.' },
            { 'Trade the Tandem Necklace +2 to the Magian Moogle (Blue) in Ru\'Lude Gardens at (H-5) to start Magian Trial 4446.' },
            { 'Have your Adventuring Fellow weapon-skill any XP-giving monster 20 times while you wear the Tandem Necklace +2.', sub = {
                { 'Weapon Skills must hit to count.' },
                { 'Set the Fellow to Fierce Attacker and avoid clubs (Moonlight and Starlight do not count).' },
            } },
            { 'After 20 successful weapon skills, trade the Tandem Necklace +2 to the Magian Moogle (Blue) to receive a Mythril Meed.' },
            { 'Trade the Mythril Meed to Luto Mewrilah to complete the quest.' },
        },
        notes             = {

            { 'Weapons in Ro\'Maeve have decent HP for the Fellow to build TP and WS.', sub = {
                { 'Not far from the Survival Guide.' },
            } },
            { 'Bring a Red Mage and use Distract, Paralyze, Slow, Addle, Blind.' },
        },
    },
    ['Your Crystal Ball'] = {
        title             = 'Your Crystal Ball',
        starting_npc      = 'Kurou-Morou, Lower Jeuno - (I-7)',
        subtitle          = 'Fortune-teller In Training',
        repeatable        = 'No',
        description       = 'Create your own crystal ball to have your fortune told.',
        required_fame     = 'Jeuno Fame Level: 2',
        level_restriction = 'None',
        pack              = 'None',
        requirements      = 'Ahriman Lens',
        rewards           = 'Kurou-Morou will tell your fortune.',
        previous_quest    = 'None',
        next_quest        = 'Never to Return',
        walkthrough       = {

            { 'Speak to Kurou-Morou, the fortune teller in Lower Jeuno above the Auction House — he asks for a Crystal Ball.' },
            { 'Obtain an Ahriman Lens (Ex item, not on AH) from Evil Eye type mobs.', sub = {
                { 'Eyes spawn in Ranguemont Pass, Beaucedine Glacier, and Xarcabard.' },
            } },
            { 'Head to the Maze of Shakhrami and go to (G-5) on the first map, east of the Attohwa Chasm exit.', sub = {
                { 'Fastest route: Voidwatch Warp to Tavnazia → Attohwa Chasm via any Atmacite Refiner, then south to zone into Maze of Shakhrami.' },
                { 'Tavnazia unlock: 75+ players can talk to Owain to get a Hyacinth stratum abyssite — no VW battles required.' },
                { 'The 1000 cruor requirement can be met via a Copper Voucher, Abyssea fodder kills, or previously earned VW cruor.' },
            } },
            { 'At the top of the path, find a Rockwell.' },
            { 'Trade your Ahriman Lens to the Rockwell — you receive "You submerged the Ahriman Lens into the pool of water."' },
            { 'Zone, then return and check the Rockwell to obtain your Divination Sphere.', sub = {
                { 'Zoning alone may not be enough — you may need to wait until the next game day.' },
            } },
            { 'Return to Kurou-Morou and trade him the Divination Sphere to complete the quest — he will tell your fortune on request.' },
        },
    },
}

quest_info['ahturhgan'] = {
    ['A Stygian Pact'] = {
        title             = 'A Stygian Pact',
        starting_npc      = 'Nashmeira, Imperial Ward',
        subtitle          = 'Sworn to the Dark Divinity',
        repeatable        = 'Yes',
        description       = 'To reclaim the soul of Prince Luzaf, you have have entered an unholy covenant with the Dark Divinity. What trials await you as Odin\'s knight? Shrink not from the shadows, and be strong in your convictions, that you might emerge unscathed!',
        required_fame     = 'Unknown',
        level_restriction = 'None',
        pack              = 'None',
        requirements      = 'Defeat Odin a total of 12 previous times in The Rider Cometh and Unwavering Resolve, choosing to "Release thy knight" in the cutscene following every completion.',
        rewards           = 'Imperial Gold Piece Choice of one: Pact with Odin Aesir Torque Aesir Mantle Aesir Ear Pendant 10,000 gil',
        previous_quest    = 'Unwavering Resolve',
        next_quest        = 'None',
        walkthrough       = {

            { 'Speak to Naja Salaheem in Aht Urhgan Whitegate (I-10) for a cutscene that begins the quest.' },
            { 'Examine the Imperial Whitegate at Aht Urhgan Whitegate (L-8/9).' },
            { 'Speak to Yoyoroon in Nashmau at (G-6).' },
            { 'Obtain a Timeworn Talisman from Ephramadian Shades in Arrapago Reef or Caedarva Mire.', sub = {
                { 'Talismans obtained prior to starting this quest can be used.' },
                { 'Shades are found west of the Dvucca Isle Staging Point around (G-10), and near the Survival Guide for Caedarva Mire.' },
            } },
            { 'Trade the Timeworn Talisman with a Sutlac, Irmik Helvasi, or both to Yoyoroon in Nashmau.', sub = {
                { 'Appraisal can fail; trading both food items along with the talisman gives the highest chance of success.' },
                { 'On failure, obtain another Timeworn Talisman and food items.' },
                { 'Yoyoroon will not accept Sutlac +1 or Irmik Helvasi +1.' },
            } },
            { 'On success, zone and speak to Yoyoroon again to receive the Key Item Talisman of the rebel gods.' },
            { 'Return to Imperial Whitegate for a cutscene to receive the Key Items Talisman key and Spatial pressure barometer.' },
            { 'Enter Hazhalm Testing Grounds and examine the Entry Gate for a cutscene.', sub = {
                { 'Same area as Einherjar; quickest access is the Caedarva Mire Home Point.' },
            } },
            { 'Examine the Entry Gate again to enter the BCNM against Odin Prime.', sub = {
                { 'Odin Prime casts Paralyze, Dispelga, and elemental magic.' },
                { 'He can spawn up to 3 Odin Images.' },
                { 'At low percentage, prolonged fights risk Zantetsuken.' },
            } },
            { 'After winning, choose your reward in the cutscene.' },
            { 'Examine the Imperial Whitegate at (L-8/9) for a cutscene.' },
            { 'Speak to Naja Salaheem at (I-10) for a cutscene to complete the quest.' },
        },
    },
    ['A Taste of Honey'] = {
        title             = 'A Taste of Honey',
        starting_npc      = 'Qutiba, Aht Urhgan Whitegate (K-12)',
        subtitle          = 'None',
        repeatable        = 'No',
        description       = 'Qutiba wants you to bring her three pots of white honey so she can make the famous Near Eastern confectionery "irmik helvasi."',
        required_fame     = 'Unknown',
        level_restriction = 'None',
        pack              = 'None',
        requirements      = 'White Honey x3',
        rewards           = 'Irmik Helvasi and additional recipes.',
        previous_quest    = 'Vanishing Act',
        next_quest        = 'None',
        walkthrough       = {

            { 'After completing Vanishing Act, re-zone and wait one Earth minute.', sub = {
                { 'Mog House does not count as zoning.' },
            } },
            { 'Speak to Qutiba at (K-12) for a cutscene.', sub = {
                { 'You may need to talk to her several times and agree to listen to a recipe before the cutscene plays.' },
            } },
            { 'Trade Qutiba three pots of White Honey for another cutscene and your reward.', sub = {
                { 'Trading more White Honey re-shows the Irmik Helvasi recipe; you may also get an additional food recipe.' },
            } },
        },
    },
    ['Against All Odds'] = {
        title             = 'Against All Odds',
        starting_npc      = 'Ratihb - Aht Urhgan Whitegate (J-12)',
        subtitle          = 'Paragon of Corsair Excellence',
        repeatable        = 'No',
        description       = 'Qultada has been captured by the Empire. Head to Arrapago with the Seagull Phratrie crew and save your captain!',
        required_fame     = 'Aht Urhgan Fame Level: Unknown',
        level_restriction = 'Level 50+ Corsair',
        pack              = 'Treasures of Aht Urhgan',
        requirements      = 'Key Item Life float',
        rewards           = 'Corsair\'s Tricorne',
        previous_quest    = 'Navigating the Unfriendly Seas',
        next_quest        = 'Breaking the Bonds of Fate',
        note              = ': After receiving the cutscene, you may commission Corsair Artifact Armor from Leleroon. You may chose the order in which you receive the armor and may commission a new piece one Vana\'diel day (one Earth hour) after the last piece was completed. The rest of this quest may be completed on any job. If you lose the battle, you may return to get another key item after one real life day (midnight JST). Head to the The Ashu Talif in Arrapago Reef through the Dvucca Isle Staging Point or Alzadaal Undersea Ruins. To access the Cutter, first travel to Dvucca Isle Staging Point and leave the staging point putting you in Caedarva Mire (Map 2). Head West to (F-9) and zone into Arrapago Reef through entrance 3. Head North to (H-8) to find the Cutter. The Survival Guide in Caedarva Mire is also close: From the Guide, head out of the tunnel to the West, then South to enter Arrapago Reef right beside the Ashu Talif. Approach the Cutter for a cutscene. Examine the Cutter to enter a battlefield against Yazquhl and Gowam. Up to six people may enter the fight. There is no level cap, and buffs will wear on entry. Trusts can be summoned in this fight. You will receive your reward immediately following the cutscene after the fight. Artifact Trace After receiving the quest Against All Odds, you may commission Corsair Artifact Armor from Leleroon. You may chose the order in which you receive the armor and may commission a new piece immediately after the last piece was completed. Corsair Artifact Armor Armor Ingredients Coin Cost Corsair\'s Gants Gold Thread Karakul Leather Red Grass Cloth Wamoura Silk Imperial Mythril Piece x4 Corsair\'s Bottes Karakul Leather Lm. Bf. Leather Mythril Sheet Wolf Felt Imperial Mythril Piece x4 Corsair\'s Frac Gold Chain Red Grass Cloth Sailcloth Velvet Cloth Imperial Gold Piece',
        walkthrough       = {

            { 'On Corsair, head to the Shararat Teahouse in Aht Urhgan Whitegate (K-12) for a cutscene and Key Item: Life float.', sub = {
                { 'After this cutscene you may commission Corsair Artifact Armor from Leleroon (one piece per Vana\'diel day).' },
                { 'The rest of the quest may be done on any job.' },
                { 'If you lose the battle, you may return for another Life float after one real-life day (midnight JST).' },
            } },
            { 'Head to The Ashu Talif in Arrapago Reef via Dvucca Isle Staging Point or Alzadaal Undersea Ruins.', sub = {
                { 'From Dvucca Isle Staging Point, exit into Caedarva Mire (Map 2), head west to (F-9), zone into Arrapago Reef through entrance 3, then north to (H-8) for the Cutter.' },
                { 'Alternative: the Caedarva Mire Survival Guide — from the Guide, go west out of the tunnel then south into Arrapago Reef right beside the Ashu Talif.' },
            } },
            { 'Approach the Cutter for a cutscene.' },
            { 'Examine the Cutter to enter a battlefield against Yazquhl and Gowam.', sub = {
                { 'Up to 6 players; no level cap; buffs wear on entry.' },
                { 'Trusts can be summoned.' },
            } },
            { 'Receive your reward in the cutscene after the fight.' },
            { '── Corsair AF commission materials (Leleroon) ──' },
            { 'Gold Thread' },
            { 'Karakul Leather' },
            { 'Red Grass Cloth' },
            { 'Wamoura Silk' },
