    ['The Rider Cometh'] = {
        title             = 'The Rider Cometh',
        starting_npc      = 'Nashmeira, Imperial Ward',
        subtitle          = 'Heir of the Blighted Gloom',
        repeatable        = 'No',
        description       = 'Ominous rumors circulating among the mercenary ranks speak of Dark Rider sightings deep within the Hazhalm Testing Grounds. Could this occurrence bear any connection to the unsealed spatial distortion? It falls to you to investigate.',
        required_fame     = 'Unknown',
        level_restriction = 'None',
        pack              = 'None',
        requirements      = 'Eternal Mercenary (Complete all ToAU Missions)',
        rewards           = 'Imperial Gold Piece Choice of one: Pact with Odin Aesir Torque Aesir Mantle Aesir Ear Pendant 10,000 gil Access to Key ItemStygian Pact phantom gem',
        previous_quest    = 'None',
        next_quest        = 'Unwavering Resolve',
        note              = 'If you are having difficulties flagging this quest, it might just not appear as flagged in your quest log. Carry on by skipping the Walahra Temple cutscene as well as the first cutscene with Totoroon and see if you can progress when trading a Timeworn Talisman and food item.',
        walkthrough       = {

            { 'Examine Imperial Whitegate in Aht Urhgan Whitegate at (J/K-8) for a cutscene.' },
            { 'Speak to Yoyoroon in Nashmau at (G-6) to receive Key Item: Message from Yoyoroon.', sub = {
                { 'Yoyoroon is on the upper level stalls — not Yuyuroon on the lower level.' },
                { 'If you speak to him as Blue Mage, you must change jobs and speak to him again.' },
            } },
            { 'Obtain a Timeworn Talisman from Ephramadian Shades in Arrapago Reef or Caedarva Mire.', sub = {
                { 'Use the Survival Guide to Caedarva Mire and ride west then south to find Shades, or continue into Arrapago Reef (Cutter Mission CS area).' },
                { 'Alternatively, buy an Arrapago Ring from Asrahd in Aht Urhgan Whitegate (I-8) for 100 Imperial standing accolades — it warps next to Shades near the Cutter.' },
                { 'Shades also spawn west of Dvucca Isle Staging Point around (G-10), and near the Caedarva Mire Survival Guide.' },
                { 'Talismans obtained before starting this quest can be used.' },
            } },
            { 'Trade the Timeworn Talisman plus a Sutlac and/or Irmik Helvasi to Yoyoroon in Nashmau.', sub = {
                { 'Trading both foods with the talisman gives the highest appraisal success chance.' },
                { 'Sutlac and Irmik Helvasi are sold by Fayeewah and Yafaaf at the Shararat Teahouse in Whitegate.' },
                { 'Yoyoroon will not accept Sutlac +1 or Irmik Helvasi +1.' },
                { 'If appraisal fails, you must obtain another Timeworn Talisman and the food items again.' },
                { 'On success, zone and speak to Yoyoroon again to receive Key Item: Talisman of the rebel gods.' },
            } },
            { 'Examine Imperial Whitegate at Aht Urhgan Whitegate (L-8/9) for a cutscene and Key Item: Talisman key.', sub = {
                { 'If no cutscene plays, inspect the Imperial Whitegate instead.' },
                { 'Subsequent attempts require bringing a new Talisman of the rebel gods directly to the Imperial Whitegate door.' },
            } },
            { 'Travel to Hazhalm Testing Grounds and examine the Entry Gate for a cutscene.', sub = {
                { 'Same area as Einherjar — quickest route is the Caedarva Mire Home Point.' },
            } },
            { 'Examine the Entry Gate again to enter the BCNM against Odin Prime.', sub = {
                { 'Trust Magic CANNOT be used in this BCNM.' },
                { 'Odin Prime casts Paralyze, Dispelga, and elemental magic, and can spawn up to 3 Odin Images.' },
                { 'At low HP, Odin can use Zantetsuken if the fight drags on.' },
            } },
            { 'After winning, choose your reward in the cutscene.' },
            { 'Examine Imperial Whitegate at Aht Urhgan Whitegate (L-8/9) for a cutscene to complete the quest.', sub = {
                { 'If you get the Trust: Nashmeira cutscene instead, finish it, then re-examine the gate to complete this quest.' },
            } },
        },
    },
