    ['Waking Dreams'] = {
        title             = 'Waking Dreams',
        starting_npc      = 'Kerutoto, Windurst Waters South (J-8) (HP #3)',
        subtitle          = 'Heir to the Realm of Dreams',
        repeatable        = 'Yes',
        description       = 'Diabolos has informed Kerutoto that he is waiting for you at the Shrouded Maw in Pso\'Xja, buried deep in the northern lands. You must respond to his summons so that Kerutoto can meditate free of trouble.',
        required_fame     = 'Windurst Fame Level: 3',
        level_restriction = 'None',
        pack              = 'None',
        requirements      = 'Darkness Named',
        rewards           = 'Diabolos (Avatar) 15,000 Gil Diabolos\'s Pole Diabolos\'s Earring Diabolos\'s Torque Diabolos\'s Ring',
        previous_quest    = 'None',
        next_quest        = 'None',
        walkthrough       = {

            { 'Speak to Kerutoto in Windurst Waters South (J-8) (Home Point #3) for a cutscene that begins the quest and grants Key Item Vial of dream incense.', sub = {
                { 'Home Point #3 is just south of Kerutoto.' },
            } },
            { 'Head to Pso\'Xja Home Point #1.', sub = {
                { 'If you lack the Home Point: enter Pso\'Xja from Beaucedine Glacier (H-8); displacement sequence is red, purple, red, purple (buffs are lost each pass). Take the elevator down, go forward, turn left at the intersection, examine the Stone Gate and choose Yes to use the Pso\'Xja pass Key Item. Home Point is past the gate on the left.' },
            } },
            { 'Head down the steps into The Shrouded Maw.' },
            { 'Select the Memento Circle and pick Waking Dreams.' },
            { 'Defeat Diabolos Prime to receive Key Item Whisper of dreams.', sub = {
                { 'Uses Drain, Aspir, Sleepga II, Dispelga, Blindga, Noctoshield (Phalanx), Dream Shroud (MAB/MDB up), Camisado (physical), Nether Blast (ranged dark), Ultimate Terror (attribute down AoE), Nightmare (dark AoE sleep + HP drain), Ruinous Omen (Astral Flow, random % HP loss AoE).' },
                { 'Tiles vanish during the fight, dropping players into a Diremites-filled pit.' },
            } },
            { 'Return to Kerutoto with the whisper for several reward options including the ability to summon Diabolos.' },
        },
        notes             = {

            { 'Trust Magic cannot be used in this BCNM.' },
            { 'Up to 6 party members may enter the arena.' },
            { 'Each party member must hold their own Key Item Vial of dream incense.' },
            { 'Time limit is 30 minutes.' },
            { 'Only one of Kerutoto\'s rewards may be held at a time.' },
            { 'Quest may be repeated once per Earth day.' },
            { 'First clear: the Shrouded Maw event with Diabolos changes based on your Chains of Promathia mission progress.' },
        },
    },
    ['Waking the Beast'] = {
        title             = 'Waking the Beast',
        starting_npc      = '??? (Carbuncle), La Theine Plateau (G-6)',
        subtitle          = 'Disturber of Slumber, or Interrupter of Dreams',
        repeatable        = 'Yes',
        description       = 'Carbuncle wants you to visit all the protocrystals and gather the elemental energy of the sleeping gods. Will their imminent awakening mean fortune or doom for Vana\'diel? Only Carbuncle\'s ancient friend at the Full Moon Fountain may know...',
        required_fame     = 'Other Fame Level: Unknown',
        level_restriction = 'None',
        pack              = 'None',
        requirements      = 'Key Item Eye of flames Key Item Eye of frost Key Item Eye of gales Key Item Eye of storms Key Item Eye of tides Key Item Eye of tremors',
        rewards           = 'Carbuncle\'s Pole Carbuncle\'s Cuffs Garuda\'s Sickle Ifrit\'s Bow Leviathan\'s Couse Ramuh\'s Mace Shiva\'s Shotel Titan\'s Baselarde',
        previous_quest    = 'Trial by Earth Trial by Fire Trial by Ice Trial by Lightning Trial by Water Trial by Wind',
        next_quest        = 'None',
        note              = 'You must first have obtained the 6 summonable Celestial avatars before you are presented with the Rainbow resonator.',
        walkthrough       = {

            { 'You must first obtain the 6 summonable Celestial avatars before being presented with the Rainbow resonator.' },
            { 'Speak to Carbuncle at the ??? (G-6) in La Theine Plateau.' },
            { 'Collect six key items by defeating harder versions of the 6 Celestial avatars at their respective Cloisters; select "Waking the Beast" at each BCNM entrance.', sub = {
                { 'Up to 18 players may enter; Trust Magic is not usable.' },
                { 'Avatars are level 85, have meritable Blood Pacts, and can use Astral Flow at any time.' },
                { 'Each avatar is supported by four elementals that share hate, cure the avatar with tier IV nukes, and inflict their element\'s debuff on melee. New elementals only respawn when the avatar uses its meritable Blood Pact (max four at a time); if the BP target dies to the BP, no elemental spawns.' },
                { 'Defeating each avatar awards its respective key item.' },
            } },
            { 'Once all six key items are obtained, proceed to Full Moon Fountain for a cutscene and the final battle.', sub = {
                { 'HP Warp Toraimarai Canal is the fastest route. Up to 18 players may enter.' },
                { 'Battle starts vs Carbuncle. At 75% HP he is replaced by 1 of the 6 avatars; after that avatar dies Carbuncle returns at 75%.' },
                { 'At 50% HP he is replaced by 2 of the remaining avatars; after those die Carbuncle returns at 50%.' },
                { 'At 25% HP he is replaced by the final 3 avatars; after those die, five Carbuncle Primes spawn at once. Each uses Searing Light (multiple times possible) before dying. Defeat all five to win.' },
            } },
            { 'The six key items are kept on defeat but consumed on victory.' },
            { 'During the post-battle cutscene, choose whether to return the Faded ruby to Carbuncle (determines title).' },
            { 'Return to the ??? (G-6) in La Theine Plateau to receive your title.', sub = {
                { 'Return the ruby — title "Disturber of Slumber".' },
                { 'Keep the ruby — title "Interrupter of Dreams".' },
            } },
            { '── Strategy: Duo by Two Summoners ──' },
            { 'Defeat Carbuncles and avatars up until the 3-avatar phase.' },
            { 'Defeat two of the three; bring the last to ~10% without using Blood Pact: Rages.' },
            { 'One SMN Astral Flows and uses Alexander.' },
            { 'After Alexander, that SMN siphons MP while the other SMN finishes the last avatar with melee only.' },
            { 'When the 5 Carbuncle Primes spawn, each SMN takes one and kills it with a Blood Pact, removing Searing Light pressure.' },
            { 'Clean up the remaining 3 Primes.' },
        },
    },
