    ['A Thirst for the Ages'] = {
        title             = 'A Thirst for the Ages',
        starting_npc      = 'Roskin, Eastern Adoulin - (H-8)',
        subtitle          = 'None',
        repeatable        = 'No',
        description       = 'Search Adoulin\'s bifurcated districts and beyond to find clues pertaining to the formation of its current political body. The riches you\'ll receive for this classified mission may just amount to more than you could ever imagine.',
        required_fame     = 'Adoulin Fame Level: 1',
        level_restriction = 'None',
        pack              = 'Seekers of Adoulin',
        requirements      = 'Frontier Soda Pickaxe',
        rewards           = '2010 Experience Points 1000 Bayld',
        previous_quest    = 'None',
        next_quest        = 'A Thirst for the Eons',
        note              = ': There are treants in this small area that aggro sound. Make sure you\'ve got sneak up. The ??? is on the line between E/F-6. Bivouac #2 is closest. Western Adoulin Talk to Nikkhail at the Pioneers\' Coalition (E-8) to receive Key Item Copy of the alliance agreement and 150 Experience Points. Eastern Adoulin Examine the two ???s in the Scouts\' Coalition (F-9) to receive Key Item Record of the 17th Assembly and 100 Experience Points, as well as Copy of "Adoulin\'s Patroness" and 10 Experience Points. It may be possible to complete this quest without obtaining Copy of "Adoulin\'s Patroness". Information Needed However, since the ???s are right next to each other, it should make no difference. Optional: Yahse Hunting Grounds Talk to Javolio (K-9) to receive Key Item Ulbukan navigation chart and 250 Experience Points. Return to Roskin who will ask you which documents are important. Answer that Key Item Royal fiat banning colonization, Key Item Record of the 17th Assembly, and Key Item Copy of the alliance agreement are important but not Key Item Copy of "Adoulin\'s Patroness" or Key Item Ulbukan navigation chart. Even if you did not obtain the Key Item Ulbukan navigation chart, he may still ask about it. You will then be rewarded with 500 Bayld and asked to come back another day. Speak to Roskin again after waiting 1 game day. He explains that after paying off his debts he doesn\'t have much of a reward for you. However, he gives you an additional 500 Bayld and says that he\'ll make it up to you in the future. If you told him that all 5 pages were important he will only give you 2 Bayld as a reward. Retrieved from "https://www.bg-wiki.com/index.php?title=A_Thirst_for_the_Ages&oldid=679289" window[\'nitroAds\'].createAd(\'bgwiki-anchor\', { "refreshLimit": 0, "refreshTime": 30, "format": "anchor", "anchor": "bottom", "report": { "enabled": true, "icon": true, "wording": "Report Ad", "position": "top-right" },  "mediaQuery": "(min-width: 0px)" }); window[\'nitroAds\'].createAd(\'nitro-video\', { "refreshTime": 30, "format": "floating", "report": { "enabled": true, "icon": true, "wording": "Report Ad", "position": "top-left" } }); Categories: QuestsAdoulin QuestsInformation NeededEastern Adoulin QuestsFFXI Wiki',
        walkthrough       = {

            { 'Speak with Roskin to begin the quest; he says he is thirsty and could use a Frontier Soda.' },
            { 'Return to Roskin with a Frontier Soda for a cutscene.', sub = {
                { 'Frontier Soda — from Bernegeois at (G-8) in Eastern Adoulin for 125 Gil.' },
            } },
            { '── Documents to Collect ──' },
            { 'Ceizak Battlegrounds — use a Pickaxe on the ??? at (F-6) for Key Item Royal fiat banning colonization and 1500 EXP.', sub = {
                { 'Treants in this small area aggro sound — bring sneak.' },
                { 'The ??? is on the line between E/F-6; Bivouac #2 is closest.' },
            } },
            { 'Western Adoulin — speak to Nikkhail at the Pioneers\' Coalition (E-8) for Key Item Copy of the alliance agreement and 150 EXP.' },
            { 'Eastern Adoulin — examine the two ???s in the Scouts\' Coalition (F-9) for Key Item Record of the 17th Assembly (100 EXP) and Copy of \'Adoulin\'s Patroness\' (10 EXP).', sub = {
                { 'Quest may be completable without Copy of \'Adoulin\'s Patroness\', but the ???s are adjacent so it makes no difference.' },
            } },
            { 'Optional: Yahse Hunting Grounds — speak to Javolio (K-9) for Key Item Ulbukan navigation chart and 250 EXP.' },
            { 'Return to Roskin; he asks which documents are important.', sub = {
                { 'Answer: Royal fiat banning colonization, Record of the 17th Assembly, and Copy of the alliance agreement are important — but NOT Copy of \'Adoulin\'s Patroness\' or Ulbukan navigation chart.' },
                { 'Even if you did not obtain the Ulbukan navigation chart, he may still ask about it.' },
            } },
            { 'Receive 500 Bayld and a request to return another day.' },
            { 'Speak to Roskin again after waiting 1 game day for an additional 500 Bayld.', sub = {
                { 'If you told him all 5 pages were important, he gives only 2 Bayld instead.' },
            } },
        },
    },
