            { 'Wait a game day before beginning the next quest.' },
        },
    },
    ['Forging New Bonds'] = {
        title             = 'Forging New Bonds',
        starting_npc      = 'Octavien, Eastern Adoulin (I-8)',
        subtitle          = 'None',
        repeatable        = 'No',
        description       = 'Scour the lands for a capable blacksmith who can fashion a sword worthy of displaying at the Order of Orvail\'s traditional ceremony.',
        required_fame     = 'Adoulin Fame Level: Unknown',
        level_restriction = 'Level 90+ Rune Fencer',
        pack              = 'None',
        requirements      = 'Sowilo Claymore -or- Elixir Ifritite x1',
        rewards           = 'Beorc Sword Ability to commission Runeist Armor crafting at Tomato Vantage Point',
        previous_quest    = 'Endeavoring to Awaken',
        next_quest        = 'Legacies Lost and Found',
        note              = 'If you are defeated, you do not need another Ifritite to summon the NM again. Simply interact with the Molten Rift again to make it reappear. You do not need to be a Rune Fencer for the fight. The surrounding Apex Efts are non-aggressive. Upon defeating it, you will get the Frost-encrusted flame gem Key Item. Check the Inconspicuous Barrel in Western Adoulin (I-4) for a cutscene, where you will lose the Rune saber and Frost-encrusted flame gem key items. Check the Inconspicuous Barrel after one game day has passed. There will be a note instructing you to talk to Octavien. Talk with Octavien to receive the Beorc Sword. Note: Completing this quest allows the player to commission the three non-quested pieces of Rune Fencer artifact armor from the Tomato Vantage Point at (E-10) Rala Waterways. Western Adoulin Mog House is closest entrance. Retrieved from "https://www.bg-wiki.com/index.php?title=Forging_New_Bonds&oldid=761971" window[\'nitroAds\'].createAd(\'bgwiki-anchor\', { "refreshLimit": 0, "refreshTime": 30, "format": "anchor", "anchor": "bottom", "report": { "enabled": true, "icon": true, "wording": "Report Ad", "position": "top-right" },  "mediaQuery": "(min-width: 0px)" }); window[\'nitroAds\'].createAd(\'nitro-video\', { "refreshTime": 30, "format": "floating", "report": { "enabled": true, "icon": true, "wording": "Report Ad", "position": "top-left" } }); Categories: QuestsAdoulin QuestsRune Fencer Artifact QuestsEastern Adoulin QuestsFFXI Wiki',
        walkthrough       = {

            { 'Zone and speak to Octavien in Eastern Adoulin (I-8) near the Sverdhried Hillock waypoint after finishing the last quest.', sub = {
                { 'You no longer need to be a Rune Fencer after this point.' },
                { 'Optional: speak with Gaddiux at Inventors\' Coalition in Western Adoulin (J-10) on the blacksmith\'s whereabouts.' },
            } },
            { 'Check the Inconspicuous Barrel in Western Adoulin (I-4), in the alley near the Adoulin Waterfront waypoint.', sub = {
                { 'Yestin-Ovestin appears on the wall and asks for a Rune saber and a Frost-encrusted flame gem.' },
                { 'Optional: return to Octavien for additional dialogue.' },
            } },
            { 'Check the Tomato Vantage Point in the Arboretum in Rala Waterways (E-10) for a cutscene with Jerra Ndala.', sub = {
                { 'Closest access is from the entrance near Western Adoulin\'s Mog House.' },
                { 'Ask about the Rune saber — trade a Sowilo Claymore OR an Elixir to the Tomato Vantage Point to get Key Item Rune saber.' },
                { 'Ask for the Frost-encrusted flame gem — she gives you Key Item Flask of fruiserum.' },
            } },
            { 'Travel to Moh Gates and trade an Ifritite to the Molten Rift at (K-8) for a cutscene; you lose the Flask of fruiserum.', sub = {
                { 'Morimar Frontier Station waypoint is the fastest way to Moh Gates; if unavailable, Yahse Bivouac #1 is another fast route.' },
                { 'You must pass through a Colonization Reive at I-7.' },
                { 'For multi-person runs, everyone must trade their Ifritite before spawning the NM.' },
            } },
            { 'Check the Molten Rift again to spawn NM Staumarth.', sub = {
                { 'Soloable by a 118 RUN/DNC using Trusts; resists everything except Thunder and spams Spectral Floe/Scouring Spate (up to 30s Terror or strips gear) — bring gear sets.' },
                { 'On defeat, re-interact with the Molten Rift to respawn it without another Ifritite.' },
                { 'You do not need to be Rune Fencer for the fight.' },
                { 'Surrounding Apex Efts are non-aggressive.' },
                { 'On victory, receive Key Item Frost-encrusted flame gem.' },
            } },
            { 'Check the Inconspicuous Barrel in Western Adoulin (I-4) for a cutscene; you lose the Rune saber and Frost-encrusted flame gem.' },
            { 'Check the Inconspicuous Barrel again after one game day for a note instructing you to talk to Octavien.' },
            { 'Speak with Octavien to receive the Beorc Sword.' },
            { 'Completing this quest allows commissioning the three non-quested Rune Fencer artifact pieces from the Tomato Vantage Point at (E-10) Rala Waterways (closest entrance: Western Adoulin Mog House).' },
        },
    },
